sources.consumer/source/authority.py:
"""Root approval comparator and the broker material-provenance envelope."""

from bill import project_artifacts
from whole_join import admit_approved_kernel, derive_root_input
from canonical import domain_digest, projection_digest
from contract import ContractError, is_commit, is_digest, is_fingerprint
from pins import (
    A009_SHA256,
    CANDIDATE_COMMIT,
    CANDIDATE_TREE,
    GOLDEN_COMMIT,
    PRODUCER_MAY_MINT,
)
from schema_validate import validate_document
from semantics import validate_receipt_semantics

_BINDINGS = (
    "issuer_id",
    "key_fingerprint",
    "capability_sha256",
    "attempt_generation",
    "artifact_set_sha256",
    "signer_set_sha256",
    "manifest_sha256",
    "recipe_sha256",
    "rootfs_sha256",
    "golden_sha256",
    "tool_sha256",
    "candidate_commit",
    "candidate_tree",
    "golden_commit",
    "bill_sha256",
)


def approval_body_digest(approval):
    body = {key: value for key, value in approval.items() if key not in ("approval_sha256", "projection_digest")}
    return domain_digest("friday.lab815.approval-body.v1", body)


def require_external_issuer(approval, expected, schema, root_issuer_sha256, approval_result=None):
    validate_document(approval, schema)
    if approval["produced_by_this_package"] is not False or PRODUCER_MAY_MINT:
        raise ContractError("producer_minted_approval")
    if approval["effects_granted"] is not False:
        raise ContractError("effects_granted")
    if approval["candidate_commit"] != CANDIDATE_COMMIT or approval["candidate_tree"] != CANDIDATE_TREE:
        raise ContractError("candidate_binding")
    if approval["golden_commit"] != GOLDEN_COMMIT or not is_commit(approval["golden_commit"]):
        raise ContractError("golden_binding")
    body_digest = approval_body_digest(approval)
    if approval["approval_sha256"] == body_digest:
        raise ContractError("digest_cycle")
    if approval["projection_digest"] != projection_digest(approval):
        raise ContractError("projection_mismatch")
    if expected is None:
        return {
            "status": "NOT_PROVEN",
            "cause": "external_approval_absent",
            "projection_digest": approval["projection_digest"],
            "publisher_proof": False,
        }
    validate_document(expected, schema)
    if expected["attempt_generation"] != approval["attempt_generation"]:
        raise ContractError("generation_mismatch")
    for key in _BINDINGS:
        if approval[key] != expected[key]:
            raise ContractError("issuer_binding")
    if approval["signature_sha256"] != expected["signature_sha256"] or approval["custody_sha256"] != expected["custody_sha256"]:
        raise ContractError("issuer_custody")
    if not is_digest(approval["approval_sha256"]):
        raise ContractError("approval_digest")
    if root_issuer_sha256 is None:
        return {
            "status": "NOT_PROVEN",
            "cause": "root_issuer_unpinned",
            "projection_digest": approval["projection_digest"],
            "publisher_proof": False,
        }
    if approval["approval_sha256"] != root_issuer_sha256:
        raise ContractError("issuer_pin")
    if approval_result is None:
        return {
            "status": "NOT_PROVEN",
            "cause": "approval_result_absent",
            "projection_digest": approval["projection_digest"],
            "publisher_proof": False,
        }
    if type(approval_result) is not dict or approval_result.get("decision") != "AUTHENTICATED":
        return {
            "status": "NOT_PROVEN",
            "cause": "approval_result_unproven",
            "projection_digest": approval["projection_digest"],
            "publisher_proof": False,
        }
    if approval_result.get("body_sha256") != body_digest:
        raise ContractError("approval_body")
    identity_keys = (
        "capability_sha256",
        "custody_sha256",
        "dependency_closure_sha256",
        "environment_digest",
        "executable_sha256",
        "issuer_id",
        "key_fingerprint",
        "signature_sha256",
        "verifier_sha256",
    )
    for key in identity_keys:
        value = approval_result.get(key)
        if value is None or value == "":
            return {
                "status": "NOT_PROVEN",
                "cause": "approval_identity_incomplete",
                "projection_digest": approval["projection_digest"],
                "publisher_proof": False,
            }
    for key in ("capability_sha256", "custody_sha256", "issuer_id", "key_fingerprint", "signature_sha256"):
        if key not in approval:
            continue
        left = approval[key]
        if left is None or left == "":
            continue
        if left != approval_result[key]:
            raise ContractError("issuer_binding")
    for actual_key, expected_key in (
        ("capability_sha256", "expected_capability_sha256"),
        ("dependency_closure_sha256", "expected_dependency_closure_sha256"),
        ("environment_digest", "expected_environment_digest"),
        ("executable_sha256", "expected_executable_sha256"),
        ("verifier_sha256", "expected_verifier_sha256"),
    ):
        expected_value = approval_result.get(expected_key)
        if expected_value is None or expected_value == "":
            return {
                "status": "NOT_PROVEN",
                "cause": "approval_identity_unbound",
                "projection_digest": approval["projection_digest"],
                "publisher_proof": False,
            }
        if approval_result.get(actual_key) != expected_value:
            raise ContractError("issuer_binding")
    status = "STRUCTURALLY_BOUND"
    cause = "approval_compared"
    return {
        "status": status,
        "cause": cause,
        "projection_digest": approval["projection_digest"],
        "publisher_proof": False,
    }


def signer_set_digest(signers):
    if signers is None:
        return None
    if type(signers) is not list:
        raise ContractError("signer_set")
    rows = []
    for item in signers:
        if not is_fingerprint(item):
            raise ContractError("signer_fingerprint")
        rows.append(item)
    if len(rows) != len(set(rows)):
        raise ContractError("signer_set")
    if not rows:
        return None
    return domain_digest("friday.lab820.signer-set.v1", sorted(rows))


def materials_digest(artifacts, authority_identity, recipe_sha256):
    body = {
        "artifacts": [
            {
                "abi": item.get("abi"),
                "class": item["class"],
                "custody_sha256": item.get("custody_sha256"),
                "filename": item["filename"],
                "format": item.get("format"),
                "key_id": item.get("key_id"),
                "sha256": item.get("sha256"),
                "signature_sha256": item.get("signature_sha256"),
                "signer_fingerprint": item.get("signer_fingerprint"),
                "size": item.get("size"),
                "source": item.get("source"),
                "tag": item.get("tag"),
                "verifier_sha256": item.get("verifier_sha256"),
            }
            for item in artifacts
        ],
        "authority": authority_identity,
        "recipe_sha256": recipe_sha256,
    }
    return domain_digest("friday.lab820.materials.v1", body)


def build_material_provenance(approval, recipe, comparison_status, schema, observations=None, admitted_signers=None, computed=None, pins=None):
    computed = {} if computed is None else computed
    artifacts = project_artifacts(recipe, observations, pins)
    kernel=admit_approved_kernel(artifacts,computed,pins)
    manifest_sha256 = computed["manifest_sha256"] if "manifest_sha256" in computed else approval["manifest_sha256"]
    recipe_sha256 = computed["recipe_sha256"] if "recipe_sha256" in computed else approval["recipe_sha256"]
    rootfs_sha256 = computed["rootfs_sha256"] if "rootfs_sha256" in computed else approval["rootfs_sha256"]
    golden_sha256 = computed["golden_sha256"] if "golden_sha256" in computed else approval["golden_sha256"]
    tool_sha256 = computed["tool_sha256"] if "tool_sha256" in computed else approval["tool_sha256"]
    for artifact in artifacts:
        if artifact["class"] == "recipe" and artifact.get("sha256") is None and is_digest(recipe_sha256):
            artifact["sha256"] = recipe_sha256
            artifact["upstream_authority"] = "COMPUTED_OUTPUT"
        elif artifact["class"] == "tool" and artifact.get("sha256") is None and is_digest(tool_sha256):
            artifact["sha256"] = tool_sha256
            artifact["upstream_authority"] = "COMPUTED_OUTPUT"
        elif artifact["class"] == "golden" and artifact.get("sha256") is None and is_digest(golden_sha256):
            artifact["sha256"] = golden_sha256
            artifact["upstream_authority"] = "COMPUTED_OUTPUT"
    ordered = [
        {
            "class": artifact["class"],
            "custody_sha256": artifact.get("custody_sha256"),
            "filename": artifact["filename"],
            "key_id": artifact.get("key_id"),
            "sha256": artifact.get("sha256"),
            "signature_sha256": artifact.get("signature_sha256"),
            "signer_fingerprint": artifact.get("signer_fingerprint"),
            "size": artifact.get("size"),
            "source": artifact.get("source"),
            "verifier_sha256": artifact.get("verifier_sha256"),
        }
        for artifact in artifacts
    ]
    owner_status = "PENDING"
    authorities = []
    if comparison_status == "STRUCTURALLY_BOUND":
        owner_status = "STRUCTURALLY_BOUND"
        authorities = [approval["issuer_id"]]
    envelope = {
        "schema": "material-provenance.v1",
        "manifest_sha256": manifest_sha256,
        "assembly_recipe_sha256": recipe_sha256,
        "creation_tool_sha256": tool_sha256,
        "approved_authorities": authorities,
        "artifacts": artifacts,
        "owner_approval": {
            "status": owner_status,
            "artifact_order_sha256": domain_digest("friday.lab815.artifact-order.v1", ordered),
            "signer_set_sha256": signer_set_digest(admitted_signers),
            "manifest_sha256": manifest_sha256,
            "candidate_commit": approval["candidate_commit"],
            "attempt_generation": approval["attempt_generation"],
            "rootfs_sha256": rootfs_sha256,
            "golden_sha256": golden_sha256,
            "recipe_sha256": recipe_sha256,
            "broker_contract_sha256": A009_SHA256,
            "publisher_proof": False,
        },
    }
    validate_document(envelope, schema)
    return envelope


def project_trust(
    approval,
    expected,
    raw_receipt,
    approval_schema,
    receipt_schema,
    provenance_schema,
    projection_schema,
    recipe,
    root_issuer_sha256,
    approval_result=None,
    observations=None,
    admitted_signers=None,
    authority_identity=None,
    computed=None,
    pins=None,
    receipt_records=None,
):
    validate_document(raw_receipt, receipt_schema)
    validate_receipt_semantics(raw_receipt)
    if raw_receipt["proof_status"] not in ("NOT_PROVEN", "REFUSED", "STRUCTURALLY_BOUND", "AUTHENTICATED"):
        raise ContractError("receipt_status")
    if raw_receipt["proof_status"] == "AUTHENTICATED" and raw_receipt["verification_result_sha256"] is None:
        raise ContractError("verification_result_absent")
    decision = require_external_issuer(approval, expected, approval_schema, root_issuer_sha256, approval_result)
    envelope = build_material_provenance(
        approval, recipe, decision["status"], provenance_schema, observations, admitted_signers, computed, pins,
    )
    if approval["artifact_set_sha256"] is not None:
        observed = domain_digest("friday.lab822.artifact-set.v1", [
            {
                "class": item["class"],
                "custody_sha256": item.get("custody_sha256"),
                "filename": item["filename"],
                "key_id": item.get("key_id"),
                "sha256": item.get("sha256"),
                "signature_sha256": item.get("signature_sha256"),
                "signer_fingerprint": item.get("signer_fingerprint"),
                "size": item.get("size"),
                "source": item.get("source"),
                "verifier_sha256": item.get("verifier_sha256"),
            }
            for item in envelope["artifacts"]
        ])
        if observed != approval["artifact_set_sha256"]:
            raise ContractError("artifact_set")
    signers = []
    records = receipt_records if type(receipt_records) is list else []
    for record in records:
        if type(record) is not dict:
            continue
        if record.get("decision") not in ("STRUCTURALLY_BOUND", "AUTHENTICATED"):
            continue
        finger = record.get("key_fingerprint")
        if is_fingerprint(finger) and finger not in signers:
            signers.append(finger)
    if not signers:
        for item in observations or []:
            if type(item) is not dict:
                continue
            finger = item.get("signer_fingerprint")
            if is_fingerprint(finger) and finger not in signers:
                signers.append(finger)
    if not signers and type(admitted_signers) is list:
        for item in admitted_signers:
            if is_fingerprint(item) and item not in signers:
                signers.append(item)
    computed_signers = signer_set_digest(signers if signers else None)
    envelope["owner_approval"]["signer_set_sha256"] = computed_signers
    if approval["signer_set_sha256"] is not None and approval["signer_set_sha256"] != computed_signers:
        raise ContractError("signer_set")
    identity = authority_identity if authority_identity is not None else {
        "issuer_id": approval["issuer_id"],
        "key_fingerprint": approval["key_fingerprint"],
    }
    materials_sha256 = materials_digest(envelope["artifacts"], identity, envelope["assembly_recipe_sha256"])
    for key in ("manifest_sha256", "golden_sha256", "recipe_sha256", "rootfs_sha256"):
        if approval[key] is not None and envelope["owner_approval"][key] != approval[key]:
            raise ContractError("broker_identity")
    if approval["tool_sha256"] is not None and envelope["creation_tool_sha256"] != approval["tool_sha256"]:
        raise ContractError("broker_identity")
    release_trusted = False
    if release_trusted:
        raise ContractError("synthetic_release_trust")
    projection = {
        "schema": "friday.lab815.trusted-root-projection.v1",
        "comparison_status": decision["status"],
        "release_trusted": release_trusted,
        "reason": decision["cause"],
        "projection_digest": decision["projection_digest"],
        "issuer_id": approval["issuer_id"],
        "key_fingerprint": approval["key_fingerprint"],
        "artifact_set_sha256": approval["artifact_set_sha256"],
        "signer_set_sha256": approval["signer_set_sha256"],
        "rootfs_sha256": approval["rootfs_sha256"],
        "golden_sha256": approval["golden_sha256"],
        "tool_sha256": approval["tool_sha256"],
        "attempt_generation": approval["attempt_generation"],
        "effects_denied": True,
        "publisher_proof": False,
        "provenance_sha256": domain_digest("friday.lab815.provenance-link.v1", {
            "artifact_order_sha256": envelope["owner_approval"]["artifact_order_sha256"],
            "assembly_recipe_sha256": envelope["assembly_recipe_sha256"],
            "creation_tool_sha256": envelope["creation_tool_sha256"],
            "manifest_sha256": envelope["manifest_sha256"],
            "materials_sha256": materials_sha256,
            "owner_status": envelope["owner_approval"]["status"],
            "receipt_vector_sha256": domain_digest(
                "friday.lab832.receipt-vector.v1",
                receipt_records if type(receipt_records) is list else [],
            ),
        }),
    }
    validate_document(projection, projection_schema)
    kernel = admit_approved_kernel(envelope["artifacts"], computed, pins)
    root_input_path = derive_root_input(approval, raw_receipt, computed, envelope, kernel, approval_result)
    if projection['comparison_status']=='STRUCTURALLY_BOUND' and root_input_path['closed'] is not True:
        projection['comparison_status']='NOT_PROVEN'
        projection['reason']='root_input_incomplete'
    return {
        "projection": projection,
        "provenance": envelope,
        "materials_sha256": materials_sha256,
        "root_input_path": root_input_path,
    }

sources.consumer/source/body_scope.py:
"""Call-local body roots: originals survive every error until actual custody.

No original exception/traceback/frame is cleared for a public failure. Public
failure objects are separate, bounded metadata; private custody is never wire
approval. Whole native/body acceptance and finite outside-owner completion
remain distinct requirements.
"""
import contextvars
import functools
from contract import ContractError
from resource_meter import checkpoint, reserve_allocation, current

_SCOPES = contextvars.ContextVar('publisher_body_scopes', default=None)

def register(lease):
    scope = _SCOPES.get()
    if scope is None:
        raise ContractError('body_scope_absent')
    scope['leases'].append(lease)

def temporary_slot(meter, count):
    scope = _SCOPES.get()
    if scope is None:
        raise ContractError('body_scope_absent')
    reserve_allocation(1024)
    cell = {'meter': meter, 'count': count, 'charged': False,
            'body': None, 'retired': False, 'attempted': False, 'producer': scope['producer']}
    # Establish the actual cell before charge or body-producing effects.
    scope['temporary'].append(cell)
    meter.charge_slots(count)
    cell['charged'] = True
    return cell

def retire_temporary(cell):
    if cell['retired']:
        return True
    if cell['attempted']:
        return False
    cell['attempted'] = True
    if cell['charged']:
        if cell['meter'].release_slots(cell['count']) is not True:
            return False
        cell['charged'] = False
    cell['body'] = None
    cell['retired'] = True
    return True

def begin_producer(lease):
    scope = _SCOPES.get()
    if scope is None:
        raise ContractError('body_scope_absent')
    previous = scope['producer']
    scope['producer'] = lease
    return scope, previous

def end_producer(scope, previous):
    scope['producer'] = previous

def retire_producer(scope, lease):
    # The actual producer frame returned normally, and the caller now owns the
    # returned full bytes under its already-charged lease. Failed producer
    # frames never reach this transition, so partial assemblies stay charged.
    for cell in scope['temporary']:
        if cell['producer'] is lease and retire_temporary(cell) is not True:
            return False
    return True

def _metadata_only(value):
    todo = [value]
    count = 0
    while todo:
        item = todo.pop()
        count += 1
        if count > 1000000:
            raise ContractError('count')
        if count % 512 == 0:
            checkpoint()
        if type(item) is dict:
            if any(type(k) is not str for k in item):
                raise ContractError('body_alias_escape')
            reserve_allocation(len(item) * 8)
            todo.extend(item.values())
        elif type(item) in (list, tuple):
            reserve_allocation(len(item) * 8)
            todo.extend(item)
        elif type(item) not in (str, int, bool, type(None)):
            raise ContractError('body_alias_escape')

def _public_failure(exc):
    safe = 'abcdefghijklmnopqrstuvwxyz0123456789_'
    if type(exc) is ContractError:
        cause = exc.cause if type(exc.cause) is str and 1 <= len(exc.cause) <= 128 and all(c in safe for c in exc.cause) else 'body_consumer_error'
        stage = exc.stage if type(exc.stage) is str and 1 <= len(exc.stage) <= 128 and all(c in safe for c in exc.stage) else None
        return ContractError(cause, stage)
    if type(exc) is KeyboardInterrupt:
        return KeyboardInterrupt()
    if type(exc) is SystemExit:
        return SystemExit(1)
    return ContractError('body_consumer_error')

def _retire_scope(scope):
    complete = True
    for lease in scope['leases']:
        try:
            if lease.retire() is not True:
                scope['cleanup'].append(ContractError('body_cleanup'))
                complete = False
        except BaseException as secondary:
            scope['cleanup'].append(secondary)
            complete = False
    for cell in scope['temporary']:
        try:
            if retire_temporary(cell) is not True:
                scope['cleanup'].append(ContractError('body_cleanup'))
                complete = False
        except BaseException as secondary:
            scope['cleanup'].append(secondary)
            complete = False
    return complete

def document_scope(function):
    @functools.wraps(function)
    def consume(*args, **kwargs):
        reserve_allocation(16384)
        scope = {'primary': None, 'traceback': None, 'leases': [],
                 'temporary': [], 'cleanup': [], 'body_roots': None, 'producer': None,
                 'entered': False, 'returned': False, 'retired': False,
                 'context_transition': None}
        whole = current()
        if whole is not None:
            whole.body_scopes.append(scope)
        token = None
        failure = None
        result = None
        try:
            reserve_allocation(4096)
            transition={'sol070_context_transition':True,'token':None,'var':_SCOPES,
                'before':contextvars.copy_context(),'set_value':scope,
                'reset_attempted':False,'reset_confirmed':False,'reset_error':None}
            scope['context_transition']=transition
            token = _SCOPES.set(scope)
            transition['token']=token
            scope['entered'] = True
            result = function(*args, **kwargs)
            _metadata_only(result)
            scope['returned'] = True
        except BaseException as exc:
            # Exact strong roots keep BOTH cause/context branches, original
            # traceback objects, frames, locals and partial buffers transitively.
            # No graph traversal, clear_frames, chain rewiring or body clearing.
            scope['primary'] = exc
            scope['traceback'] = exc.__traceback__
            result = None
            failure = _public_failure(exc)
        finally:
            if token is not None:
                try:
                    transition['reset_attempted']=True
                    _SCOPES.reset(token)
                    transition['reset_confirmed']=True
                except BaseException as secondary:
                    transition['reset_confirmed']=None
                    transition['reset_error']=secondary
                    scope['cleanup'].append(secondary)
                    if failure is None:
                        failure = _public_failure(secondary)
            # A successful consumer frame has gone and returned only metadata.
            # A failed release retains the original body in the lease/cell.
            # Failure frames/bodies stay charged until the actual whole receiver.
            if scope['primary'] is None and not scope['cleanup']:
                scope['retired'] = _retire_scope(scope)
            if scope['cleanup']:
                if whole is not None:
                    whole.cleanup_fault = True
                if failure is None:
                    failure = ContractError('body_cleanup')
            if scope['retired'] and whole is not None:
                whole.discard_body_scope(scope)
        if failure is not None:
            # An unmetered internal call has no module-global/unbounded bucket.
            # Its exact private graph follows the original caller's exception,
            # so the existing outer error receiver sees it rather than a label.
            # This attribute is NOT serialized into the public refusal document.
            failure._private_body_custody = scope
            raise failure from None
        return result
    return consume

sources.consumer/source/canonical.py:
"""Canonical JSON and domain-separated digests. Parsing requires canonical bytes."""

from resource_meter import HashlibProxy
hashlib = HashlibProxy()
import json

from contract import MAX_DEPTH, MAX_DOCUMENT_BYTES, MAX_ITEMS, MAX_STRING, ContractError
from resource_meter import canonical_bound, json_preflight, checkpoint, reserve_allocation

PROJECTION_DOMAIN = "friday.lab815.projection.v1"
CANONICAL_DOMAIN = "friday.lab815.canonical.v1"


def canonical_bytes(document):
    canonical_bound(document)
    try:
        text = json.dumps(
            document,
            allow_nan=False,
            ensure_ascii=True,
            separators=(",", ":"),
            sort_keys=True,
        )
    except (TypeError, ValueError, RecursionError, MemoryError) as exc:
        raise ContractError("canonical_encoding") from exc
    return (text + "\n").encode("ascii")


def require_canonical(raw, value):
    if raw != canonical_bytes(value):
        raise ContractError("not_canonical")
    return value


def domain_digest(domain, document):
    if type(domain) is not str or not domain.isascii() or not 1 <= len(domain) <= 128:
        raise ContractError("domain")
    if any(character.isspace() for character in domain):
        raise ContractError("domain")
    body = canonical_bytes(document)
    return hashlib.sha256(domain.encode("ascii") + b"\0" + body).hexdigest()


def projection_digest(envelope):
    if type(envelope) is not dict:
        raise ContractError("envelope")
    body = {key: value for key, value in envelope.items() if key != "projection_digest"}
    return domain_digest(PROJECTION_DOMAIN, body)


def _pairs(pairs):
    seen = set()
    document = {}
    for key, value in pairs:
        if key in seen:
            raise ContractError("duplicate_key")
        seen.add(key)
        document[key] = value
    return document


def _reject_constant(_name):
    raise ContractError("nonfinite")


def _walk(value, depth, max_depth, max_items, max_string):
    if depth > max_depth:
        raise ContractError("depth")
    if type(value) is dict:
        reserve_allocation(32 + len(value) * 16)
        if len(value) > max_items:
            raise ContractError("count")
        for key, item in value.items():
            if type(key) is not str or len(key) > max_string:
                raise ContractError("key")
            _walk(item, depth + 1, max_depth, max_items, max_string)
        return
    if type(value) is list:
        reserve_allocation(32 + len(value) * 16)
        if len(value) > max_items:
            raise ContractError("count")
        for item in value:
            _walk(item, depth + 1, max_depth, max_items, max_string)
        return
    if type(value) is str and len(value) > max_string:
        raise ContractError("string_length")
    if type(value) not in (str, int, bool, type(None)):
        raise ContractError("json_type")


def parse_exact(text, max_bytes=MAX_DOCUMENT_BYTES, max_depth=MAX_DEPTH, max_items=MAX_ITEMS, max_string=MAX_STRING):
    if type(text) is str:
        if len(text)>max_bytes: raise ContractError('document_size')
        reserve_allocation(len(text)*4+1)
        raw = text.encode("utf-8")
    elif type(text) is bytes:
        raw = text
    else:
        raise ContractError("document_type")
    if len(raw) > max_bytes:
        raise ContractError("document_size")
    json_preflight(raw, max_bytes, max_depth, max_items, max_string)
    try:
        value = json.loads(raw.decode("utf-8"), object_pairs_hook=_pairs, parse_constant=_reject_constant)
    except ContractError:
        raise
    except (UnicodeError, json.JSONDecodeError, ValueError, RecursionError, MemoryError) as exc:
        raise ContractError("json") from exc
    _walk(value, 1, max_depth, max_items, max_string)
    return require_canonical(raw, value)

sources.consumer/source/capability.py:
"""External verifier capability bound to hashed bytes and an expected authority."""

from resource_meter import HashlibProxy
hashlib = HashlibProxy()

from canonical import domain_digest
from contract import ContractError, is_digest, is_fingerprint
from pins import (
    A033_GPGV_SHA256,
    NODESOURCE_FINGERPRINT_NOT_AUTHORITY,
    UBUNTU_ARGV,
    UBUNTU_EXECUTABLE,
    UBUNTU_FINGERPRINT,
    UBUNTU_ISSUER_ID,
    UBUNTU_KEYRING_SHA256,
)
from schema_validate import validate_document

_TOKEN = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789._-/")


def closure_digest(dependencies):
    if type(dependencies) is not list:
        raise ContractError("dependency_inventory")
    rows = []
    seen = set()
    for item in dependencies:
        if type(item) is not dict:
            raise ContractError("dependency_inventory")
        if "path" not in item or "sha256" not in item:
            raise ContractError("dependency_inventory")
        path = item["path"]
        digest = item["sha256"]
        if type(path) is not str or not path or path in seen or not is_digest(digest):
            raise ContractError("dependency_inventory")
        seen.add(path)
        rows.append({
            "custody_sha256": item.get("custody_sha256"),
            "gid": item.get("gid"),
            "mode": item.get("mode"),
            "path": path,
            "sha256": digest,
            "size": item.get("size"),
            "uid": item.get("uid"),
        })
    rows.sort(key=lambda row: row["path"])
    if not rows:
        raise ContractError("dependency_inventory_empty")
    return domain_digest("friday.lab815.dependency-closure.v1", rows)


def _environment_rows(entries):
    if type(entries) is not list:
        raise ContractError("environment_entries")
    rows = []
    seen = set()
    for item in entries:
        if type(item) is not dict:
            raise ContractError("environment_entries")
        name = item.get("name")
        value = item.get("value")
        if type(name) is not str or type(value) is not str or name == "" or name in seen:
            raise ContractError("environment_entries")
        seen.add(name)
        rows.append({"name": name, "value": value})
    rows.sort(key=lambda row: row["name"])
    return rows


def capability_digest(capability):
    body = {key: value for key, value in capability.items() if key != "verified_by_tool"}
    return domain_digest("friday.lab815.capability-body.v1", body)


def _pending(cause):
    return {
        "status": "NOT_PROVEN",
        "cause": cause,
        "publisher_proof": False,
        "effects_denied": True,
        "verified_by_tool": False,
    }


def _bound(cause):
    return {
        "status": "STRUCTURALLY_BOUND",
        "cause": cause,
        "publisher_proof": False,
        "effects_denied": True,
        "verified_by_tool": False,
    }


def _argv_matches(argv, kind):
    if type(argv) is not list or len(argv) != 4:
        raise ContractError("argv")
    if tuple(argv[:3]) != UBUNTU_ARGV or argv[0] != UBUNTU_EXECUTABLE:
        raise ContractError("argv")
    tail = argv[3]
    if type(tail) is not str or not 1 <= len(tail) <= 80 or any(character not in _TOKEN for character in tail):
        raise ContractError("argv_target")
    if kind == "ubuntu-inrelease" and tail != "inrelease":
        raise ContractError("argv_target")
    if kind == "node-shasums256" and tail != "shasums256":
        raise ContractError("argv_target")
    return True


def bind_verification_result(result, capability, raw, body, armor, archive, schema):
    validate_document(result, schema)
    if result["produced_by_this_package"] is not False:
        raise ContractError("self_issued_result")
    if result["issuer_id"] != capability["issuer_attestation"]["issuer_id"]:
        raise ContractError("result_issuer")
    if result["algorithm"] != capability["algorithm_class"]:
        raise ContractError("algorithm_binding")
    if result["argv"] != capability["argv"]:
        raise ContractError("argv")
    if result["environment_digest"] != capability["environment_digest"]:
        raise ContractError("environment_digest")
    if result["keyring_sha256"] != capability["keyring_sha256"]:
        raise ContractError("keyring_mismatch")
    if result["capability_sha256"] != capability_digest(capability):
        raise ContractError("capability_binding")
    if raw is None or body is None or armor is None:
        return _pending("verification_bytes_absent")
    if hashlib.sha256(raw).hexdigest() != result["raw_sha256"]:
        raise ContractError("result_binding")
    if hashlib.sha256(body).hexdigest() != result["body_sha256"]:
        raise ContractError("result_binding")
    if hashlib.sha256(armor).hexdigest() != result["armor_sha256"]:
        raise ContractError("result_binding")
    if archive is None:
        if result["archive_sha256"] is not None or result["archive_size"] is not None:
            raise ContractError("archive_binding")
    elif hashlib.sha256(archive).hexdigest() != result["archive_sha256"] or len(archive) != result["archive_size"]:
        raise ContractError("archive_binding")
    if result["decision"] == "NOT_PROVEN":
        return _pending("result_decision_unproven")
    if result["decision"] not in ("STRUCTURALLY_BOUND", "AUTHENTICATED"):
        raise ContractError("result_decision")
    attested = capability["issuer_attestation"]
    if result["issuer_result_sha256"] is None or result["custody_sha256"] is None or result["attestation_sha256"] is None:
        return _pending("independent_result_absent")
    if result["attestation_sha256"] != attested["attestation_sha256"] or attested["attestation_sha256"] is None:
        raise ContractError("attestation_linkage")
    if result["custody_sha256"] != attested["custody_sha256"] or attested["custody_sha256"] is None:
        raise ContractError("custody_linkage")
    if result["dependency_closure_sha256"] != capability["dependency_closure_sha256"]:
        raise ContractError("dependency_closure")
    if attested["signature_sha256"] is None or result["issuer_result_sha256"] != attested["signature_sha256"]:
        return _pending("signature_unpinned")
    if result["decision"] == "AUTHENTICATED":
        if capability["dependency_status"] != "BOUND":
            return _pending("dependency_not_bound")
        if any(type(item) is not dict or item.get("status") != "BOUND" for item in capability["dependencies"]):
            return _pending("unproven_dependency_claim")
        return {
            "status": "AUTHENTICATED",
            "cause": "result_authenticated",
            "publisher_proof": False,
            "effects_denied": True,
            "verified_by_tool": True,
        }
    return _bound("result_bound")


def authenticate_capability(
    capability,
    expected,
    result,
    raw,
    body,
    armor,
    archive,
    capability_schema,
    result_schema,
    approved_fingerprint,
):
    validate_document(capability, capability_schema)
    if capability["produced_by_this_package"] is not False:
        raise ContractError("self_issued_capability")
    if capability["signer_supplied_by_candidate"] is not False:
        raise ContractError("candidate_signer")
    kind = capability["document_kind"]
    if capability["algorithm_class"] not in ("openpgp-sha256", "openpgp-sha512"):
        raise ContractError("algorithm_class")
    if capability["key_fingerprint"] == NODESOURCE_FINGERPRINT_NOT_AUTHORITY:
        raise ContractError("nodesource_not_this_archive")
    if not is_fingerprint(capability["key_fingerprint"]):
        raise ContractError("fingerprint")
    _argv_matches(capability["argv"], kind)
    if capability["executable"] != capability["argv"][0]:
        raise ContractError("executable_binding")
    environment_digest = domain_digest("friday.lab815.environment.v1", _environment_rows(capability["environment_entries"]))
    if capability["environment_digest"] != environment_digest:
        raise ContractError("environment_digest")
    attested = capability["issuer_attestation"]
    if attested["produced_by_this_package"] is not False:
        raise ContractError("self_issued_attestation")
    if kind == "ubuntu-inrelease":
        if capability["key_fingerprint"] != UBUNTU_FINGERPRINT:
            raise ContractError("fingerprint_mismatch")
        if capability["keyring_sha256"] != UBUNTU_KEYRING_SHA256:
            raise ContractError("keyring_mismatch")
        if attested["issuer_id"] != UBUNTU_ISSUER_ID:
            raise ContractError("issuer_mismatch")
        if capability["executable_sha256"] not in (None, A033_GPGV_SHA256):
            raise ContractError("executable_pin")
    elif kind != "node-shasums256":
        raise ContractError("document_kind")
    if capability["dependency_status"] == "BOUND" and not capability["dependencies"]:
        raise ContractError("unproven_dependency_claim")
    if capability["dependencies"]:
        digested = closure_digest(capability["dependencies"])
        if capability["dependency_closure_sha256"] != digested:
            raise ContractError("dependency_closure")
    elif capability["dependency_closure_sha256"] is not None or capability["dependency_status"] == "BOUND":
        raise ContractError("dependency_inventory_empty")
    if capability["verified_by_tool"] is True and result is None:
        return _pending("tool_flag_without_result")
    linked = None
    if result is not None:
        linked = bind_verification_result(result, capability, raw, body, armor, archive, result_schema)
        if linked["status"] not in ("STRUCTURALLY_BOUND", "AUTHENTICATED"):
            return linked
    if expected is None:
        return _pending("expected_authority_unpinned")
    validate_document(expected, capability_schema)
    for key in (
        "algorithm_class",
        "argv",
        "dependency_closure_sha256",
        "dependency_status",
        "document_kind",
        "environment_digest",
        "executable_sha256",
        "key_fingerprint",
        "keyring_sha256",
    ):
        if expected[key] != capability[key]:
            raise ContractError("expected_capability")
    if expected["executable"] != capability["executable"]:
        raise ContractError("executable_binding")
    if expected["environment_entries"] != capability["environment_entries"]:
        raise ContractError("environment_entries")
    if expected["dependencies"] != capability["dependencies"]:
        raise ContractError("dependency_inventory")
    expected_attestation = expected["issuer_attestation"]
    for key in ("attestation_sha256", "custody_sha256", "issuer_id", "signature_sha256"):
        if expected_attestation[key] != attested[key]:
            raise ContractError("attestation_linkage")
    if expected_attestation["issuer_id"] != attested["issuer_id"]:
        raise ContractError("issuer_mismatch")
    if kind == "node-shasums256":
        if approved_fingerprint is None:
            return _pending("node_signer_unproven")
        if capability["key_fingerprint"] != approved_fingerprint:
            raise ContractError("fingerprint_mismatch")
    if capability["executable_sha256"] is None or capability["dependency_closure_sha256"] is None:
        return _pending("verifier_material_absent")
    if linked is None:
        return _pending("verification_bytes_absent")
    if linked["status"] == "AUTHENTICATED":
        if capability["dependency_status"] != "BOUND":
            return _pending("dependency_not_bound")
        if any(type(item) is not dict or item.get("status") != "BOUND" for item in capability["dependencies"]):
            return _pending("unproven_dependency_claim")
        return {
            "status": "AUTHENTICATED",
            "cause": "capability_authenticated",
            "publisher_proof": False,
            "effects_denied": True,
            "verified_by_tool": True,
        }
    return _bound("capability_bound")

sources.consumer/source/document_vector.py:
"""Separate whole-vector raw consumers; no cross-document concatenation.

Full externally fixed contracts are optional only for the retained pending
baseline. Their absence is explicit NOT_PROVEN, never vector acceptance.
Current imports/bytes/controls are not run by the Source preparation task.
"""
from canonical import canonical_bytes, domain_digest, parse_exact
from capability import authenticate_capability, capability_digest
from contract import ContractError, is_digest, _STAGE
from formats import parse_clearsign, parse_release, select_package, parse_deb822, iter_deb822
from ingress import load_pinned_schema
from receipt_chain import assess_node_chain, compare_archive, correspond_algorithms
from resource_meter import HashlibProxy, checkpoint
hashlib=HashlibProxy()
from whole_join import bind_other_document, join_node_projection
from body_scope import register, document_scope, begin_producer, end_producer, retire_producer

class _Lease:
    def __init__(self,held,kind,path,digest):
        self.held=held; self.kind=kind; self.path=path; self.digest=digest; self.body=None
        self._charged=False
        self._retire_attempted=False
        self._retired=False
    def __enter__(self):
        register(self)
        self.held.meter.charge_slots(1)
        self._charged=True
        scope,previous=begin_producer(self)
        try:
            self.body=self.held.get_document(self.kind,self.path,self.digest)
            if type(self.body) is not bytes:
                raise ContractError('body_not_paged')
            if retire_producer(scope,self) is not True:
                raise ContractError('body_cleanup')
            return self
        finally:
            end_producer(scope,previous)
    def __exit__(self,*args):
        # The decorated consumer owns both this body and parser aliases.
        return False
    def retire(self):
        # A refused/throwing release leaves the original charge and body owned.
        if self._retired:return True
        if self._retire_attempted:return False
        self._retire_attempted=True
        if self._charged:
            if self.held.meter.release_slots(1) is not True:
                return False
            self._charged=False
        self.body=None
        self._retired=True
        return True

def _parsed_custody(contract, row, result, capability):
    raw=contract['custody_body']
    if raw is None:return None
    body=parse_exact(raw.encode('ascii'),max_bytes=8000,max_depth=8,max_items=512,max_string=512)
    expected={'document_kind':row['document_kind'],'path':row['path'],
              'sha256':row['sha256'],'size':row['size'],
              'produced_by_this_package':False}
    # Raw custody precedes capability/result. Their complete hashes must not
    # be fed back into a body whose digest those same objects contain.
    if body!=expected:raise ContractError('custody_linkage')
    digest=domain_digest('friday.sol037.document-custody.v1',body)
    if digest!=row['custody_sha256']:raise ContractError('custody_linkage')
    if result is not None and result['custody_sha256']!=digest:
        raise ContractError('custody_linkage')
    return body

def _result_pin(contract,result):
    if result is None or contract['expected_result_sha256'] is None:return False
    if domain_digest('friday.lab815.verification-result.v1',result)!=contract['expected_result_sha256']:
        raise ContractError('result_binding')
    return True

def _selected(contract, selected, held=None):
    raw=contract['selected_body']
    ref=contract['selected_ref']
    if raw is not None and ref is not None:
        raise ContractError('selected_record')
    if raw is None:
        if ref is None:return False
        from performing_contracts import expected_body
        if selected != expected_body(held, None, ref):
            raise ContractError('selected_record')
        return True
    actual=canonical_bytes(selected)
    if actual!=raw.encode('ascii'):raise ContractError('selected_record')
    return True

def _bind_metadata(row,contract,parsed,cap,result,selected,decision,class_runtime=None):
    actual={
        'raw_sha256':row['sha256'] if parsed is None else parsed['raw_document_sha256'],
        'normalized_body_sha256':None if parsed is None else parsed['signed_body_sha256'],
        'armor_sha256':None if parsed is None else parsed['signature_armor_sha256'],
        'capability_sha256':None if cap is None else capability_digest(cap),
        'expected_capability_sha256':None if contract['expected_capability'] is None else capability_digest(contract['expected_capability']),
        'result_sha256':None if result is None else domain_digest('friday.lab815.verification-result.v1',result),
        'selected_sha256':hashlib.sha256(canonical_bytes(selected)).hexdigest(),
        'input_sha256':domain_digest('friday.sol037.document-input.v1',contract),
        'key_fingerprint':None if cap is None else cap['key_fingerprint'],
        'decision':decision,
    }
    if class_runtime is not None:
        actual['capability_sha256'] = class_runtime['capability_sha256']
        actual['expected_capability_sha256'] = class_runtime['capability_sha256']
        actual['result_sha256'] = class_runtime['result_sha256']
        if contract['expected_result_sha256'] != actual['result_sha256']:
            raise ContractError('result_binding')
    for key,value in actual.items():
        if row[key]!=value:raise ContractError('full_receipt_binding')
    return actual

@document_scope
def _ubuntu_index(index, contracts, rows, held, package_expectations):
    in_key=('ubuntu-inrelease',index['id']); pa_key=('ubuntu-packages',index['id']+'/'+index['member_name'])
    c=contracts[in_key]; row=rows[in_key]; p_row=rows[pa_key]
    release={'architecture':index['architecture'],'component':index['component'],
             'packages_sha256':index['packages_sha256'],'size':index['size'],'suite':index['suite']}
    if c['release_expected']!=release:raise ContractError('index_link')
    with _Lease(held,*in_key,row['sha256']) as signed, _Lease(held,*pa_key,p_row['sha256']) as packages:
        parsed=parse_clearsign(signed.body)
        selected=parse_release(parsed['cleartext'],release)
        if hashlib.sha256(packages.body).hexdigest()!=selected['packages_sha256'] or len(packages.body)!=selected['size']:
            raise ContractError('member_identity')
        cap=c['capability']; result=c['verification_result']
        if cap is None:
            decision={'status':'NOT_PROVEN','cause':'full_capability_absent'}
        else:
            correspond_algorithms(parsed,cap,result)
            decision=authenticate_capability(cap,c['expected_capability'],result,signed.body,
                parsed['normalized_body'],parsed['signature_armor'],None,
                load_pinned_schema('verifier-capability.v1'),load_pinned_schema('verification-result.v1'),
                c['approved_fingerprint'])
        bound_result=_result_pin(c,result)
        custody=_parsed_custody(c,row,result,cap)
        selected_bound=_selected(c,selected,held)
        metadata=_bind_metadata(row,c,parsed,cap,result,selected,decision['status'])
        closed=decision['status'] in ('AUTHENTICATED','STRUCTURALLY_BOUND') and bound_result and custody is not None and selected_bound
        out={'index':dict(index),'decision':decision,'raw_sha256':parsed['raw_document_sha256'],
             'normalized_body_sha256':parsed['signed_body_sha256'],'armor_sha256':parsed['signature_armor_sha256'],
             'packages_sha256':selected['packages_sha256'],'selected':selected,'capability':cap,
             'expected_capability':c['expected_capability'],'verification_result':result,
             'custody_body':custody,'closed':closed,'publisher_proof':False}
        out['bound_metadata']=metadata
        # Packages has a distinct admitted identity and custody, not merely the signed index alias.
        p_c=contracts[pa_key]
        p_custody=_parsed_custody(p_c,p_row,None,None)
        out['packages_bound_metadata']=_bind_metadata(p_row,p_c,None,None,None,selected,'STRUCTURALLY_BOUND')
        out['packages_custody_body']=p_custody
        out['closed']=closed and p_custody is not None and _selected(p_c,selected,held)
        wanted={(p['name'],p['version'],p['architecture'],p['filename']):p for p in package_expectations}
        complete=[]; seen=set()
        for stanza in iter_deb822(packages.body,max_bytes=80000000):
            identity=tuple(stanza.get(k,b'').decode('utf-8') for k in ('Package','Version','Architecture','Filename'))
            if identity not in wanted:continue
            if identity in seen:raise ContractError('duplicate_package')
            seen.add(identity); expected=wanted[identity]
            from contract import bounded_int
            if any(k not in stanza for k in ('Size','SHA256')) or bounded_int(stanza['Size'],2000000000,'integer_text')!=expected['size'] or stanza['SHA256'].decode('ascii')!=expected['sha256']:
                raise ContractError('package_archive_identity')
            chosen={k:expected[k] for k in ('name','version','architecture','filename','sha256','size')}
            chosen.update({'unknown_fields':sorted(set(stanza)-{'Package','Version','Architecture','Filename','Size','SHA256'}),'publisher_proof':False})
            complete.append({'fields':[{'name':k,'value_hex':v.hex()} for k,v in sorted(stanza.items())],'selected_identity':chosen})
        if seen!=set(wanted):raise ContractError('package_missing')
        out['complete_package_records']=complete
        return out

@document_scope
def _ubuntu_archive(package,index_result,contracts,rows,held):
    key=('ubuntu-archive',package['filename']); c=contracts[key]; row=rows[key]
    index=index_result['index']; p_key=('ubuntu-packages',index['id']+'/'+index['member_name'])
    expected={'name':package['name'],'version':package['version'],'architecture':package['architecture'],
              'filename':package['filename'],'sha256':package['sha256'],'size':package['size']}
    if c['package_expected']!=expected:raise ContractError('package_archive_identity')
    with _Lease(held,*key,row['sha256']) as archive:
        records=[record for record in index_result['complete_package_records'] if all(record['selected_identity'][k]==v for k,v in expected.items())]
        if len(records)!=1:raise ContractError('duplicate_package')
        complete=records[0]
        selected_bound=_selected(c,complete,held)
        archive_decision=compare_archive(archive.body,package['sha256'],package['size'])
        custody=_parsed_custody(c,row,None,None)
        metadata=_bind_metadata(row,c,None,None,None,complete,archive_decision['status'])
        return {'package':dict(package),'selected':complete,'archive_decision':archive_decision,
                'publisher_index':index_result,'custody_body':custody,'closed':index_result['closed'] and selected_bound and custody is not None,
                'bound_metadata':metadata,'publisher_proof':False}

@document_scope
def _other_document(key,row,contract,context,held):
    with _Lease(held,*key,row['sha256']) as body:
        if len(body.body)!=row['size'] or hashlib.sha256(body.body).hexdigest()!=row['sha256']:
            raise ContractError('receipt_membership')
        custody=_parsed_custody(contract,row,None,None)
        selected_obj={'document_kind':key[0],'path':key[1],
                      'sha256':hashlib.sha256(body.body).hexdigest(),'size':len(body.body)}
        selected_bound=_selected(contract, selected_obj,held)
        from performing_contracts import consume
        performing=consume(context,held,'materials',key[0]+'/'+key[1],selected_obj)
        class_bind=bind_other_document(selected_obj, contract, custody, selected_bound, performing)
        runtime_join = class_bind['class_runtime_consumer']
        bound_metadata=_bind_metadata(row,contract,None,None,None,selected_obj,class_bind['material_status'],runtime_join)
        return {'document_kind':key[0],'path':key[1],'sha256':row['sha256'],
                'size':row['size'],'custody_body':custody,'raw_bound':True,
                'material_status':class_bind['material_status'],'cause':class_bind['cause'],
                'installed_observation_status':class_bind['installed_observation_status'],
                'actor_custody_sha256':class_bind['actor_custody_sha256'],
                'actor_custody':class_bind['actor_custody'],'performing_consumer':performing,
                'bound_metadata':bound_metadata,'runtime':'NOT_RUN'}

@document_scope
def assess_document_vector(expected,context,held,receipt_index):
    if context is None or context['document_contracts'] is None:
        return {'status':'NOT_PROVEN','cause':'full_document_contract_absent','indexes':[],
                'archives':[],'node':None,'other_documents':[],'all_documents_closed':False,
                'all_materials_closed':False,'runtime':'NOT_RUN','publisher_proof':False}
    contracts={}
    for c in context['document_contracts']:
        key=(c['document_kind'],c['path'])
        if key in contracts:raise ContractError('duplicate_receipt')
        contracts[key]=c
    if set(contracts)!=set(receipt_index):raise ContractError('receipt_membership')
    for key,row in receipt_index.items():
        if row['body_held'] is not True or not is_digest(row['sha256']):raise ContractError('body_not_paged')
    _STAGE[0]='ubuntu_receipt'; indexes=[]; index_by={}
    for index in expected['ubuntu_minimum']['indexes']:
        checkpoint(); package_expectations=[p for p in expected['ubuntu_minimum']['packages'] if (p['suite'],p['component'])==(index['suite'],index['component'])]
        result=_ubuntu_index(index,contracts,receipt_index,held,package_expectations)
        indexes.append(result); index_by[(index['suite'],index['component'])]=result
    archives=[]
    for p in expected['ubuntu_minimum']['packages']:
        checkpoint(); archives.append(_ubuntu_archive(p,index_by[(p['suite'],p['component'])],contracts,receipt_index,held))
    _STAGE[0]='node_receipt'; signed_key=('node-shasums256','SHASUMS256.txt'); archive_key=('node-archive',expected['node']['filename'])
    c=contracts[signed_key]; row=receipt_index[signed_key]; a_row=receipt_index[archive_key]
    node=None
    if c['capability'] is not None:
        with _Lease(held,*signed_key,row['sha256']) as signed, _Lease(held,*archive_key,a_row['sha256']) as archive:
            node=assess_node_chain(c['capability'],c['expected_capability'],c['approved_fingerprint'],
                c['node_authoritative'],signed.body,archive.body,load_pinned_schema('verifier-capability.v1'),
                load_pinned_schema('verification-result.v1'),load_pinned_schema('raw-publisher-receipt.v1'),
                result=c['verification_result'],expected_result_sha256=c['expected_result_sha256'],
                authority_archive_sha256=expected['node']['authoritative_sha256'])
            node['raw_custody_body']=_parsed_custody(c,row,c['verification_result'],c['capability'])
            node['archive_custody_body']=_parsed_custody(contracts[archive_key],a_row,None,None)
            selected={'filename':expected['node']['filename'],'sha256':node['archive_sha256'],
                      'size':node['archive_size'],'normalized_body_sha256':node['signed_body_sha256']}
            parsed_meta={k:node[k] for k in ('raw_document_sha256','signed_body_sha256','signature_armor_sha256')}
            node['bound_metadata']=_bind_metadata(row,c,parsed_meta,c['capability'],c['verification_result'],selected,node['proof_status'])
            archive_selected={'filename':expected['node']['filename'],'sha256':hashlib.sha256(archive.body).hexdigest(),'size':len(archive.body)}
            archive_contract=contracts[archive_key]
            node['archive_bound_metadata']=_bind_metadata(a_row,archive_contract,None,None,None,archive_selected,'STRUCTURALLY_BOUND')
            node['full_contract_closed']=bool(node['proof_status'] in ('AUTHENTICATED','STRUCTURALLY_BOUND') and
                _result_pin(c,c['verification_result']) and _selected(c,selected,held) and _selected(archive_contract,archive_selected,held) and
                node['raw_custody_body'] is not None and node['archive_custody_body'] is not None)
    consumed={('ubuntu-inrelease',x['index']['id']) for x in indexes}|{('ubuntu-packages',x['index']['id']+'/'+x['index']['member_name']) for x in indexes}|{('ubuntu-archive',x['package']['filename']) for x in archives}|{signed_key,archive_key}
    others=[]
    for key,row in receipt_index.items():
        if key in consumed:continue
        _STAGE[0]='bill'
        # A separate consumer frame releases each body after all its aliases
        # are gone. The vector retains JSON metadata, not 100+ body leases.
        others.append(_other_document(key,row,contracts[key],context,held))
    raw_closed=all(x['closed'] for x in indexes+archives) and node is not None and node['full_contract_closed'] and all(x['custody_body'] is not None for x in others)
    node_projection=join_node_projection(node, expected['node'] if type(expected) is dict else None)
    doc_closed=raw_closed and node_projection['status']=='STRUCTURALLY_BOUND' and all(x['material_status']=='STRUCTURALLY_BOUND' for x in others)
    return {'status':'STRUCTURALLY_BOUND' if doc_closed else 'NOT_PROVEN','cause':'separate_full_raw_consumers',
            'indexes':indexes,'archives':archives,'node':node,'other_documents':others,
            'all_documents_closed':doc_closed,'all_materials_closed':doc_closed,'node_projection':node_projection,
            'raw_documents_bound':raw_closed,
            'runtime':'NOT_RUN','publisher_proof':False}

