"""Strict Debian control, Release, clearsign, and checksum adapters."""

from resource_meter import HashlibProxy, reserve_allocation, debit_read, checkpoint
hashlib = HashlibProxy()
import re

from contract import (
    MAX_CLEARSIGN_BYTES,
    MAX_FIELD_VALUE,
    MAX_FIELDS,
    MAX_MEMBER_SIZE,
    MAX_PACKAGES_BYTES,
    MAX_STANZAS,
    ContractError,
    bounded_int,
    is_digest,
)

_FIELD_NAME = re.compile(rb"^[A-Za-z0-9][A-Za-z0-9+.-]{0,63}$")
_SHA256_ENTRY = re.compile(rb"^([0-9a-f]{64})[ ]+([0-9]+)[ ]+([A-Za-z0-9._+/~-]+)$")
_SHASUM_LINE = re.compile(rb"^([0-9a-f]{64})  ([A-Za-z0-9._+-]+)$")
_BASE64_LINE = re.compile(rb"^[A-Za-z0-9+/=]+$")
_CHECKSUM_LINE = re.compile(rb"^=[A-Za-z0-9+/]{4}$")
_ARMOR_HEADER = re.compile(rb"^[A-Za-z0-9-]+: [A-Za-z0-9 .+_-]+$")

_BEGIN = b"-----BEGIN PGP SIGNED MESSAGE-----"
_SIGNATURE = b"-----BEGIN PGP SIGNATURE-----"
_END = b"-----END PGP SIGNATURE-----"
_SUPPORTED_HASH = {b"SHA256": "sha256", b"SHA512": "sha512"}
RELEASE_MAX_BYTES = 2000000


def parse_deb822(data, max_bytes, max_stanzas=MAX_STANZAS, max_fields=MAX_FIELDS, max_field_value=MAX_FIELD_VALUE):
    # Compatibility collector; whole-vector selection uses the streaming API.
    stanzas=[]
    for stanza in iter_deb822(data,max_bytes,max_stanzas,max_fields,max_field_value):
        reserve_allocation(8)
        stanzas.append(stanza)
    return stanzas


def iter_deb822(data, max_bytes, max_stanzas=MAX_STANZAS, max_fields=MAX_FIELDS, max_field_value=MAX_FIELD_VALUE):
    if type(data) is not bytes:
        raise ContractError("deb822_type")
    debit_read(len(data)*3)
    if len(data) > max_bytes or b"\r" in data or b"\x00" in data:
        raise ContractError("deb822_bounds")
    count=0
    current = None
    last_name = None
    start=0
    while start<len(data):
        checkpoint()
        end=data.find(b'\n',start)
        if end<0:end=len(data)
        reserve_allocation(end-start)
        raw=data[start:end]
        start=end+1
        if raw == b"":
            if current is not None:
                if not current:
                    raise ContractError("empty_stanza")
                count+=1
                if count > max_stanzas:
                    raise ContractError("stanza_count")
                yield current
            current = None
            last_name = None
            continue
        if raw.startswith((b" ", b"\t")):
            if current is None or last_name is None:
                raise ContractError("orphan_continuation")
            size=len(current[last_name])+1+len(raw)-1
            if size > max_field_value:
                raise ContractError("field_length")
            reserve_allocation(size+len(raw))
            merged = current[last_name] + b"\n" + raw[1:]
            current[last_name] = merged
            continue
        if b":" not in raw:
            raise ContractError("missing_colon")
        reserve_allocation(len(raw)*2+80)
        name, value = raw.split(b":", 1)
        if _FIELD_NAME.fullmatch(name) is None:
            raise ContractError("field_name")
        if value.startswith(b" "):
            value = value[1:]
        elif value != b"":
            raise ContractError("field_space")
        if len(value) > max_field_value:
            raise ContractError("field_length")
        reserve_allocation(len(name)*4+64)
        key = name.decode("ascii")
        if current is None:
            current = {}
        if key in current:
            raise ContractError("duplicate_field")
        if len(current) >= max_fields:
            raise ContractError("field_count")
        current[key] = value
        reserve_allocation(len(key) + len(value) + 8)
        last_name = key
    if current is not None:
        if not current:
            raise ContractError("empty_stanza")
        count+=1
        if count>max_stanzas:raise ContractError('stanza_count')
        yield current
    if not count:
        raise ContractError("stanza_count")


def normalized_body(body_lines):
    reserve_allocation(sum(len(line)+2 for line in body_lines)*2+len(body_lines)*40)
    chunks = []
    for line in body_lines:
        if line.startswith(b"- "):
            line = line[2:]
        chunks.append(line + b"\r\n")
    return b"".join(chunks)


def parse_clearsign(data, max_bytes=MAX_CLEARSIGN_BYTES):
    if type(data) is not bytes or not data.endswith(b"\n"):
        raise ContractError("clearsign_type")
    if not 32 <= len(data) <= max_bytes or b"\r" in data or b"\x00" in data:
        raise ContractError("clearsign_bounds")
    debit_read(len(data))
    reserve_allocation(len(data)*2+(len(data)+1)*40)
    lines = data.split(b"\n")[:-1]
    if not lines or lines[0] != _BEGIN:
        raise ContractError("clearsign_begin")
    index = 1
    headers = []
    while index < len(lines) and lines[index] != b"":
        if not lines[index].startswith(b"Hash: "):
            raise ContractError("clearsign_header")
        headers.append(lines[index][6:])
        index += 1
    if len(headers) != 1 or index >= len(lines) or lines[index] != b"":
        raise ContractError("clearsign_separator")
    index += 1
    body = []
    while index < len(lines) and lines[index] != _SIGNATURE:
        body.append(lines[index])
        index += 1
    if index >= len(lines) or lines[index] != _SIGNATURE:
        raise ContractError("clearsign_signature_begin")
    signature_at = index
    index += 1
    while index < len(lines) and _ARMOR_HEADER.fullmatch(lines[index]) is not None:
        index += 1
    if index >= len(lines) or lines[index] != b"":
        raise ContractError("clearsign_armor_header")
    index += 1
    base64_count = 0
    while index < len(lines) and _BASE64_LINE.fullmatch(lines[index]) is not None and not lines[index].startswith(b"="):
        base64_count += 1
        index += 1
    if base64_count < 1 or index >= len(lines) or _CHECKSUM_LINE.fullmatch(lines[index]) is None:
        raise ContractError("clearsign_armor_body")
    index += 1
    if index != len(lines) - 1 or lines[index] != _END:
        raise ContractError("clearsign_trailing_material")
    body_bytes = normalized_body(body)
    reserve_allocation(sum(len(line)+1 for line in body)*2+len(body)*40)
    clear_lines = [line[2:] if line.startswith(b"- ") else line for line in body]
    cleartext = b"\n".join(clear_lines) + (b"\n" if clear_lines else b"")
    signed_body_sha256 = hashlib.sha256(body_bytes).hexdigest()
    algorithm = _SUPPORTED_HASH.get(headers[0])
    if algorithm is None:
        raise ContractError("unsupported_hash")
    hash_header_digest = hashlib.new(algorithm, body_bytes).hexdigest()
    if algorithm == "sha256" and hash_header_digest != signed_body_sha256:
        raise ContractError("hash_correspondence")
    if algorithm == "sha512" and len(hash_header_digest) != 128:
        raise ContractError("hash_correspondence")
    if len(signed_body_sha256) != 64:
        raise ContractError("hash_correspondence")
    reserve_allocation(sum(len(line)+1 for line in lines[signature_at:])*2+len(lines)*8)
    armor = b"\n".join(lines[signature_at:]) + b"\n"
    return {
        "raw_document_sha256": hashlib.sha256(data).hexdigest(),
        "normalized_body": body_bytes,
        "cleartext": cleartext,
        "signature_armor": armor,
        "signed_body_sha256": signed_body_sha256,
        "hash_header": headers[0].decode("ascii"),
        "hash_header_digest": hash_header_digest,
        "signature_armor_sha256": hashlib.sha256(armor).hexdigest(),
        "algorithm_status": "SUPPORTED",
        "publisher_proof": False,
    }


def _decode(value, cause):
    try:
        return value.decode("utf-8")
    except UnicodeError as exc:
        raise ContractError(cause) from exc


def _ascii_bytes(value, cause):
    if type(value) is not str:
        raise ContractError(cause)
    try:
        return value.encode("ascii")
    except UnicodeError as exc:
        raise ContractError(cause) from exc


def parse_release(cleartext, expected, max_bytes=RELEASE_MAX_BYTES):
    if type(expected) is not dict:
        raise ContractError("release_expected")
    if type(cleartext) is not bytes:
        raise ContractError("release_type")
    if len(cleartext) > max_bytes:
        raise ContractError("release_bounds")
    stanzas = parse_deb822(cleartext, max_bytes=max_bytes, max_stanzas=1)
    if len(stanzas) != 1:
        raise ContractError("release_stanza_count")
    release = stanzas[0]
    for key in ("Origin", "Suite", "Components", "Architectures", "SHA256"):
        if key not in release:
            raise ContractError("release_identity_field")
    origin = _decode(release["Origin"], "release_origin")
    if origin != "Ubuntu":
        raise ContractError("release_origin")
    suite = _decode(release["Suite"], "suite")
    if suite != expected["suite"]:
        raise ContractError("suite_mismatch")
    components = release["Components"].split()
    component = _ascii_bytes(expected["component"], "component_mismatch")
    if component not in components:
        raise ContractError("component_mismatch")
    architectures = release["Architectures"].split()
    architecture = _ascii_bytes(expected["architecture"], "architecture_mismatch")
    if architecture not in architectures:
        raise ContractError("architecture_mismatch")
    member_name = component + b"/binary-" + architecture + b"/Packages"
    found = None
    for line in release["SHA256"].split(b"\n"):
        if line == b"":
            continue
        matched = _SHA256_ENTRY.fullmatch(line)
        if matched is None:
            raise ContractError("sha256_entry")
        digest, size_text, name = matched.groups()
        if name.startswith(b"/") or b".." in name.split(b"/"):
            raise ContractError("member_path")
        size = bounded_int(size_text, MAX_MEMBER_SIZE, "integer_text")
        if name == member_name:
            if found is not None:
                raise ContractError("duplicate_member")
            found = (digest.decode("ascii"), size, name.decode("ascii"))
    if found is None:
        raise ContractError("member_missing")
    if found[0] != expected["packages_sha256"] or found[1] != expected["size"]:
        raise ContractError("member_identity")
    return {
        "suite": suite,
        "component": expected["component"],
        "architecture": expected["architecture"],
        "member_name": found[2],
        "packages_sha256": found[0],
        "size": found[1],
        "publisher_proof": False,
    }


def select_package(data, expected, max_bytes=MAX_PACKAGES_BYTES):
    stanzas = iter_deb822(data, max_bytes=max_bytes)
    want = (expected["name"], expected["version"], expected["architecture"], expected["filename"])
    found = None
    for stanza in stanzas:
        identity = tuple(
            _decode(stanza[key], "package_text") if key in stanza else None
            for key in ("Package", "Version", "Architecture", "Filename")
        )
        if identity != want:
            continue
        if found is not None:
            raise ContractError("duplicate_package")
        for key in ("Package", "Version", "Architecture", "Filename", "Size", "SHA256"):
            if key not in stanza:
                raise ContractError("package_identity_field")
        size = bounded_int(stanza["Size"], MAX_MEMBER_SIZE, "integer_text")
        digest = _decode(stanza["SHA256"], "package_sha256")
        if not is_digest(digest) or size != expected["size"] or digest != expected["sha256"]:
            raise ContractError("package_archive_identity")
        if _decode(stanza["Filename"], "filename") != expected["filename"]:
            raise ContractError("filename")
        found = {
            "name": expected["name"],
            "version": expected["version"],
            "architecture": expected["architecture"],
            "filename": expected["filename"],
            "size": size,
            "sha256": digest,
            "unknown_fields": sorted(set(stanza) - {"Package", "Version", "Architecture", "Filename", "Size", "SHA256"}),
            "publisher_proof": False,
        }
    if found is None:
        raise ContractError("package_missing")
    return found


def select_shasum(cleartext, filename, authoritative_sha256):
    if type(cleartext) is not bytes or type(filename) is not str:
        raise ContractError("shasum_type")
    if len(cleartext) > MAX_CLEARSIGN_BYTES:
        raise ContractError("shasum_bounds")
    found = None
    lines = cleartext.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()
    for line in lines:
        if line == b"":
            continue
        matched = _SHASUM_LINE.fullmatch(line)
        if matched is None:
            raise ContractError("shasum_line")
        digest, name = matched.groups()
        if name.decode("ascii") == filename:
            if found is not None:
                raise ContractError("duplicate_shasum")
            found = digest.decode("ascii")
    if found is None:
        raise ContractError("shasum_missing")
    if authoritative_sha256 is None:
        return {
            "filename": filename,
            "line_sha256": found,
            "status": "NOT_PROVEN",
            "cause": "authoritative_checksum_absent",
            "publisher_proof": False,
        }
    if type(authoritative_sha256) is not str or found != authoritative_sha256:
        raise ContractError("shasum_mismatch")
    return {
        "filename": filename,
        "line_sha256": found,
        "status": "STRUCTURALLY_BOUND",
        "cause": "checksum_row_bound",
        "publisher_proof": False,
    }

sources.consumer/source/material_literals.py:
"""Actual literal PyPI selectors, separate from their explicit effective view.

An externally selected raw document and both complete selector expectations
are compared. Retained literal null and empty string are never conflated.
This is byte/selector correspondence, not publisher or installed acceptance.
"""
import json
import re
from canonical import _pairs, _reject_constant, _walk, canonical_bytes, parse_exact
from contract import ContractError
from resource_meter import HashlibProxy, json_preflight, checkpoint
from document_vector import _Lease
from body_scope import document_scope
from performing_contracts import expected_body
hashlib=HashlibProxy()

def _raw_json(raw):
    json_preflight(raw,2000000,12,512,4000000)
    try:
        value=json.loads(raw.decode('utf-8'),object_pairs_hook=_pairs,parse_constant=_reject_constant)
    except (ValueError,UnicodeError,RecursionError,MemoryError) as exc:
        raise ContractError('wheel_observation_set') from exc
    _walk(value,1,12,512,4000000)
    return value

def _name(value):
    if type(value) is not str:raise ContractError('wheel_observation_set')
    return re.sub('[-_.]+','-',value).lower()

@document_scope
def consume_wheel_literals(context,held,items,views):
    if context is None or context['wheel_literal_contracts'] is None:
        return views
    supplied={}
    for c in context['wheel_literal_contracts']:
        if c['filename'] in supplied:raise ContractError('duplicate_observation')
        supplied[c['filename']]=c
    if set(supplied)!={i['filename'] for i in items}:raise ContractError('wheel_observation_set')
    by_name={v['filename']:v for v in views}; out=[]
    for item in items:
        checkpoint(); c=supplied[item['filename']]
        with _Lease(held,'member',c['raw_document_path'],c['raw_document_sha256']) as lease:
            raw=lease.body
            document=_raw_json(raw)
            if type(document) is not dict or type(document.get('info')) is not dict or type(document.get('urls')) is not list:
                raise ContractError('wheel_observation_set')
            info=document['info']
            if _name(info.get('name'))!=_name(item['name']) or info.get('version')!=item['version']:
                raise ContractError('wheel_observation_set')
            selected=[u for u in document['urls'] if type(u) is dict and u.get('filename')==item['filename']]
            if len(selected)!=1:raise ContractError('wheel_observation_set')
            selected=selected[0]
            expected_info=expected_body(held,c['package_info_selector_body'],c['package_info_selector_ref'])
            expected_selected=expected_body(held,c['selected_artifact_selector_body'],c['selected_artifact_selector_ref'])
            if info!=expected_info or selected!=expected_selected:
                raise ContractError('selected_record')
            if type(selected.get('digests')) is not dict or selected['digests'].get('sha256')!=item['sha256'] or type(selected.get('size')) is not int or selected['size']!=item['size']:
                raise ContractError('wheel_observation')
            for k in ('url','packagetype','yanked'):
                if selected.get(k)!=c[k]:raise ContractError('wheel_observation_set')
            if c['packagetype']!='bdist_wheel' or type(c['url']) is not str or not c['url'].startswith('https://') or type(c['yanked']) is not bool:
                raise ContractError('wheel_observation_set')
            if 'requires_python' not in info or 'requires_python' not in selected:
                raise ContractError('requires_python')
            raw_info=info['requires_python']; raw_selected=selected['requires_python']
            if raw_info!=c['package_info_requires_python_raw'] or raw_selected!=c['selected_artifact_requires_python_raw']:
                raise ContractError('requires_python_normalization')
            normalize=lambda value:None if value in (None,'') else value
            if any(v is not None and type(v) is not str for v in (raw_info,raw_selected)):
                raise ContractError('requires_python')
            if normalize(raw_info)!=normalize(raw_selected) or normalize(raw_info)!=item['requires_python']:
                raise ContractError('requires_python_normalization')
            view=dict(by_name[item['filename']])
            view.update({'metadata_raw_sha256':hashlib.sha256(raw).hexdigest(),
                         'historical_metadata_raw_sha256':item['metadata_raw_sha256'],
                         'package_info_selector':info,'selected_artifact_selector':selected,
                         'package_info_selector_sha256':hashlib.sha256(canonical_bytes(info)).hexdigest(),
                         'selected_artifact_selector_sha256':hashlib.sha256(canonical_bytes(selected)).hexdigest(),
                         'requires_python_raw':raw_info,'selected_artifact_requires_python_raw':raw_selected,
                         'requires_python_effective':normalize(raw_info),
                         'normalization':'empty_string_to_null' if raw_info=='' else 'identity',
                         'literal_selector_status':'STRUCTURALLY_BOUND',
                         'selector_bound_bytes':2000000,
                         'actual_package_info_selector_bytes':len(canonical_bytes(expected_info)),
                         'actual_selected_artifact_selector_bytes':len(canonical_bytes(expected_selected)),
                         'selector_adequacy':'FULL_COMPARE_WITHIN_ORIGINAL_DOCUMENT_CAP_NOT_WHOLE_DATASET_PROOF',
                         'installed_body_runtime_custody_status':'NOT_PROVEN','publisher_proof':False})
            out.append(view)
            del raw
    return out

sources.consumer/source/performing_contracts.py:
"""Performing consumers of independent ordinary observation bodies.

The stock caller selects the expected complete body and a different producer.
The held observed body is parsed and compared in full, before any member is
used. These are future input contracts, never present runtime observations,
publisher authentication, an extraction recipe or an authority grant.
"""
from body_scope import document_scope
from canonical import canonical_bytes, domain_digest, parse_exact
from contract import ContractError, is_digest
from document_vector import _Lease
from resource_meter import HashlibProxy, checkpoint, reserve_allocation, debit_read

hashlib = HashlibProxy()
_SECTIONS = ('materials', 'operations', 'closures', 'snapshot')
_FIELDS = {'producer_id', 'target', 'input_body', 'members', 'dependencies',
           'abi', 'resources', 'runtime', 'custody', 'output_paths', 'package_bindings'}
_MEMBER = {'operation', 'path', 'kind', 'mode', 'size', 'uid', 'gid', 'nlink',
           'device', 'mount_domain', 'parent_path', 'link_target',
           'link_target_sha256', 'content_sha256', 'status', 'source_ref'}

def descriptor(context, section, target):
    if context is None or context.get('performing_contracts') is None:
        return None
    if section not in _SECTIONS:
        raise ContractError('operation_dependency')
    rows = context['performing_contracts'][section]
    chosen = None
    for row in rows:
        if row['target'] == target:
            if chosen is not None: raise ContractError('duplicate_observation')
            chosen = row
    return chosen

@document_scope
def expected_body(held, inline, ref):
    if (inline is None) == (ref is None):
        raise ContractError('selected_record')
    if inline is not None:
        if type(inline) is not str or len(inline) > 2000000 or not inline.isascii():
            raise ContractError('document_size')
        reserve_allocation(len(inline) + 1)
        raw = inline.encode('ascii')
    else:
        if type(ref) is not dict or set(ref) != {'kind','path','sha256','size','producer_id','selector_id','document_sha256','offset'} or ref['producer_id'] == ref['selector_id']:
            raise ContractError('expected_bound_to_itself')
        if type(ref['size']) is not int or not 0 < ref['size'] <= 2000000:
            raise ContractError('document_size')
        digest = ref['sha256'] if ref['document_sha256'] is None else ref['document_sha256']
        with _Lease(held, ref['kind'], ref['path'], digest) as lease:
            raw = selected_range(lease.body, ref['sha256'], ref['size'], ref['document_sha256'], ref['offset'])
    # Returning parsed JSON metadata cannot let the physical body alias escape.
    return parse_exact(raw, max_bytes=2000000, max_depth=12, max_items=512, max_string=2000000)

def selected_range(document, digest, size, document_digest=None, offset=None):
    if type(document) is not bytes or type(size) is not int or not 0 <= size <= 80000000 or not is_digest(digest):
        raise ContractError('selected_record')
    if document_digest is None:
        if offset is not None or len(document) != size:
            raise ContractError('selected_record')
        raw = document
    else:
        if not is_digest(document_digest) or type(offset) is not int or not 0 <= offset <= len(document) or size > len(document)-offset:
            raise ContractError('selected_record')
        if hashlib.sha256(document).hexdigest() != document_digest:
            raise ContractError('selected_record')
        reserve_allocation(size+64); debit_read(size)
        raw = document[offset:offset+size]
    if hashlib.sha256(raw).hexdigest() != digest:
        raise ContractError('selected_record')
    return raw

@document_scope
def _member_bytes(held, ref, expected_sha, expected_size):
    fields = set(ref) if type(ref) is dict else set()
    if fields not in ({'kind','path','sha256'}, {'kind','path','sha256','document_sha256','offset','size'}):
        raise ContractError('operation_computation')
    if ref['sha256'] != expected_sha or not is_digest(expected_sha):
        raise ContractError('operation_computation')
    if 'size' in ref and ref['size'] != expected_size:
        raise ContractError('operation_computation')
    digest = ref.get('document_sha256') or ref['sha256']
    with _Lease(held, ref['kind'], ref['path'], digest) as lease:
        selected_range(lease.body, expected_sha, expected_size, ref.get('document_sha256'), ref.get('offset'))
    return {'sha256': expected_sha, 'size': expected_size}

def _members(body, held):
    rows = body['members']
    if type(rows) is not list or not 1 <= len(rows) <= 512:
        raise ContractError('member_limit')
    reserve_allocation(len(rows) * 160 + 64)
    by_path = {}
    for row in rows:
        checkpoint()
        if type(row) is not dict or set(row) != _MEMBER:
            raise ContractError('operation_computation')
        path = row['path']
        if type(path) is not str or path in by_path:
            raise ContractError('duplicate_member')
        if row['status'] != 'STRUCTURALLY_BOUND':
            raise ContractError('operation_computation')
        for key in ('size', 'uid', 'gid', 'nlink', 'device'):
            if type(row[key]) is not int or row[key] < 0:
                raise ContractError('operation_computation')
        if row['size'] > 80000000 or row['uid'] > 65535 or row['gid'] > 65535:
            raise ContractError('operation_computation')
        roots=('/opt/friday/quality-toolchain/venv','/work/candidate','/inputs/golden')
        parent = '' if path in roots else path.rsplit('/', 1)[0] if '/' in path else ''
        if row['parent_path'] != parent or type(row['mount_domain']) is not str:
            raise ContractError('operation_computation')
        if row['kind'] == 'regular':
            if row['nlink'] != 1 or row['link_target'] is not None or row['link_target_sha256'] is not None:
                raise ContractError('operation_computation')
            _member_bytes(held, row['source_ref'], row['content_sha256'], row['size'])
        elif row['kind'] == 'directory':
            if row['nlink'] < 2 or row['source_ref'] is not None or row['link_target'] is not None or row['link_target_sha256'] is not None:
                raise ContractError('operation_computation')
        elif row['kind'] == 'symlink':
            if type(row['link_target']) is not str or row['source_ref'] is not None:
                raise ContractError('operation_computation')
            if hashlib.sha256(row['link_target'].encode('utf-8')).hexdigest() != row['link_target_sha256']:
                raise ContractError('link_target_identity')
        else:
            raise ContractError('member_kind')
        by_path[path] = row
    from whole_join import bind_member_hierarchy
    if bind_member_hierarchy(rows)['closed'] is not True:
        raise ContractError('operation_computation')
    return by_path

def _typed_domains(body, members, held, section, target):
    packages=body['package_bindings']
    if type(packages) is not list or len(packages)>350:
        raise ContractError('closure_membership')
    names=set()
    for package in packages:
        if type(package) is not dict or set(package)!={'name','members'} or type(package['name']) is not str or package['name'] in names:
            raise ContractError('closure_membership')
        names.add(package['name'])
        if type(package['members']) is not list or not package['members'] or any(path not in members for path in package['members']):
            raise ContractError('closure_membership')
    edges = body['dependencies']
    if type(edges) is not list or len(edges) > 512:
        raise ContractError('dependency_inventory')
    identities = set()
    for edge in edges:
        if type(edge) is not dict or set(edge) != {'consumer_path', 'provider_path', 'provider_sha256', 'abi'}:
            raise ContractError('dependency_inventory')
        if type(edge['consumer_path']) is not str or type(edge['provider_path']) is not str:
            raise ContractError('dependency_inventory')
        pair = (edge['consumer_path'], edge['provider_path'])
        if pair in identities or any(path not in members for path in pair):
            raise ContractError('dependency_inventory')
        identities.add(pair)
        if members[pair[1]]['content_sha256'] != edge['provider_sha256']:
            raise ContractError('dependency_closure')
        if type(edge['abi']) is not str or not edge['abi']:
            raise ContractError('dependency_closure')
    abi = body['abi']
    if type(abi) is not dict or set(abi) != {'architecture', 'python_abi', 'loader_path', 'loader_sha256', 'libraries'}:
        raise ContractError('python_abi')
    if abi['architecture'] != 'amd64' or abi['python_abi'] != 'cp314-regular':
        raise ContractError('python_abi')
    if type(abi['loader_path']) is not str:
        raise ContractError('dependency_closure')
    loader = members.get(abi['loader_path'])
    if loader is None or loader['content_sha256'] != abi['loader_sha256'] or not is_digest(abi['loader_sha256']):
        raise ContractError('dependency_closure')
    if type(abi['libraries']) is not list or any(type(p) is not str for p in abi['libraries']) or len(set(abi['libraries'])) != len(abi['libraries']):
        raise ContractError('dependency_inventory')
    if any(path not in members for path in abi['libraries']):
        raise ContractError('dependency_inventory')
    resources = body['resources']
    if type(resources) is not list or len(resources) > 512:
        raise ContractError('closure_membership')
    roles = set()
    for row in resources:
        if type(row) is not dict or set(row) != {'role', 'path', 'sha256', 'size'}:
            raise ContractError('closure_membership')
        if type(row['role']) is not str or not 1<=len(row['role'])<=80 or type(row['path']) is not str or type(row['size']) is not int or not is_digest(row['sha256']) or row['role'] in roles:
            raise ContractError('closure_membership')
        roles.add(row['role'])
        member = members.get(row['path'])
        if member is None or member['content_sha256'] != row['sha256'] or member['size'] != row['size']:
            raise ContractError('closure_body')
    from runtime_consumer import consume_runtime
    runtime = body['runtime']
    runtime_join = consume_runtime(body, members, held, section, target)
    custody = body['custody']
    if type(custody) is not dict or set(custody) != {'producer_id', 'target', 'input_sha256', 'member_inventory_sha256', 'runtime_sha256', 'resources_sha256', 'selected_by', 'effects_granted'}:
        raise ContractError('custody_linkage')
    computed = {
        'input_sha256': domain_digest('friday.a117.performing-input.v1', body['input_body']),
        'member_inventory_sha256': domain_digest('friday.a117.installed-members.v1', body['members']),
        'runtime_sha256': domain_digest('friday.a117.runtime-observation.v1', runtime),
        'resources_sha256': domain_digest('friday.a117.resources.v1', resources),
    }
    if custody['producer_id'] != body['producer_id'] or custody['target'] != body['target'] or custody['effects_granted'] is not False:
        raise ContractError('custody_linkage')
    if any(custody[k] != value for k, value in computed.items()):
        raise ContractError('custody_linkage')
    return runtime_join

@document_scope
def consume(context, held, section, target, actual_input=None):
    selected = descriptor(context, section, target)
    if selected is None:
        return None
    if selected['producer_id'] == selected['selector_id']:
        raise ContractError('expected_bound_to_itself')
    digest = selected['sha256'] if selected['document_sha256'] is None else selected['document_sha256']
    with _Lease(held, selected['kind'], selected['path'], digest) as lease:
        raw = selected_range(lease.body, selected['sha256'], selected['size'], selected['document_sha256'], selected['offset'])
        body = parse_exact(raw, max_bytes=2000000, max_depth=12, max_items=512, max_string=2000000)
        trusted = expected_body(held, selected['expected_body'], selected['expected_ref'])
        ref = selected['expected_ref']
        if ref is not None:
            if ref['selector_id'] != selected['selector_id'] or ref['producer_id'] == selected['producer_id']:
                raise ContractError('expected_bound_to_itself')
            old_offset=0 if selected['document_sha256'] is None else selected['offset']
            expected_offset=0 if ref['document_sha256'] is None else ref['offset']
            if ref['kind'] == selected['kind'] and ref['path'] == selected['path'] and expected_offset == old_offset and ref['size'] == selected['size']:
                raise ContractError('expected_bound_to_itself')
        if body != trusted or hashlib.sha256(canonical_bytes(body)).hexdigest() != selected['sha256']:
            raise ContractError('selected_record')
        if type(body) is not dict or set(body) != _FIELDS:
            raise ContractError('operation_computation')
        if body['producer_id'] != selected['producer_id'] or body['target'] != target:
            raise ContractError('result_issuer')
        if actual_input is not None and body['input_body'] != actual_input:
            raise ContractError('operation_computation')
        members = _members(body, held)
        paths = body['output_paths']
        if type(paths) is not list or not paths or len(set(paths)) != len(paths) or any(path not in members for path in paths):
            raise ContractError('operation_computation')
        runtime_join = _typed_domains(body, members, held, section, target)
        artifact_sha = actual_input['sha256'] if section=='materials' and type(actual_input) is dict and 'sha256' in actual_input else domain_digest('friday.a128.operation-artifact.v1',body['input_body'])
        if body['runtime']['artifact_sha256'] != artifact_sha:
            raise ContractError('custody_linkage')
        if section=='closures':
            required=actual_input['data_packages'] if target=='data' else actual_input['interpreter_packages']
            have={p['name'] for p in body['package_bindings']}
            if have!=set(required):raise ContractError('closure_membership')
            if target=='data' and {r['role'] for r in body['resources']}!={'certificates','fonts','locales','timezones','nss','glib','gpu'}:
                raise ContractError('closure_membership')
        if body['custody']['selected_by'] != selected['selector_id']:
            raise ContractError('custody_linkage')
        return {'body': body, 'raw_sha256': selected['sha256'],
                'selected_body_sha256': hashlib.sha256(canonical_bytes(body)).hexdigest(),
                'observed_body_ref':{k:selected[k] for k in ('kind','path','sha256','document_sha256','offset','size')},
                'expected_body_ref':selected['expected_ref'],
                'producer_id':selected['producer_id'],'selector_id':selected['selector_id'],
                'custody_sha256': domain_digest('friday.a117.actor-custody.v1', body['custody']),
                'runtime_consumer': runtime_join,
                'status': 'STRUCTURALLY_BOUND', 'publisher_proof': False,
                'runtime': 'FUTURE_PRODUCER_BOUND_INPUT_NOT_CURRENT_OBSERVATION'}

def operation_input(name, expected, composition, presented, predecessors):
    vector = composition['full_document_vector']
    other = vector['other_documents']
    def classes(kinds):
        return [row for row in other if row['document_kind'] in kinds]
    if name == 'authenticate-ubuntu-indexes':
        material = vector['indexes']
    elif name == 'authenticate-ubuntu-archives':
        material = vector['archives']
    elif name == 'authenticate-node-archive':
        material = {'consumer': vector['node'], 'projection': vector.get('node_projection')}
    elif name == 'hold-unrar-publisher-gap':
        material = {'required': expected['unrar'], 'consumers': classes(('unrar',))}
    elif name == 'authenticate-wheels':
        material = {'literal_consumers': composition['wheels'], 'body_consumers': classes(('wheel',))}
    elif name in ('map-cpython-venv', 'map-lib-dynload', 'map-native-loader'):
        material = {'platform': expected['platform'], 'closure': composition['closure_view'], 'consumers': classes(('native',))}
    elif name == 'map-browser-resources':
        material = {'browser': expected['browser'], 'consumers': classes(('browser',))}
    elif name == 'map-data-closure':
        material = {'required': expected['data_packages'], 'closure': composition['closure_view'], 'consumers': classes(('data',))}
    elif name == 'bind-candidate':
        material = {'identity': expected['candidate'], 'consumers': classes(('candidate',))}
    elif name == 'bind-golden':
        material = {'identity': expected['golden'], 'consumers': classes(('golden',))}
    elif name in ('assemble-members', 'write-final-manifest', 'external-custody'):
        # Preserve and compare every byte of complete predecessor bodies while
        # keeping the input graph acyclic and bounded in nesting depth.
        material = {'full_predecessor_output_refs': [
            {'name':row['name'],'output_sha256':row['output_sha256'],
             'body_sha256':hashlib.sha256(canonical_bytes(row['full_output_body'])).hexdigest(),
             'observed_body_ref':dict(row['performing_ref'])}
            for row in predecessors]}
    else:
        raise ContractError('recipe_operations')
    # This digest is computed from the COMPLETE already-called consumer output,
    # not copied from a claimed label. Its full preimage stays in the public
    # composition/operation outputs, while a small acyclic input avoids repeated
    # nesting of complete capabilities, inventories and predecessor bodies.
    material_ref = {'full_material_input_sha256':domain_digest(
        'friday.a128.full-called-operation-material.v1',material)}
    return {'operation': name, 'material': material_ref,
            'predecessors': [{'name': p['name'], 'output_sha256': p['output_sha256']} for p in predecessors]}

