    )
    wheel_members = []
    for item in composition["wheels"]:
        view = item
        pin = _pin_row(presented, "wheel", view["sha256"], view["size"])
        uid, gid = _owners(pin)
        wheel_members.append(_member(
            "/opt/friday/quality-toolchain/venv/lib/python3.14/site-packages/" + view["filename"],
            "regular",
            view["sha256"],
