    golden_member = _member(
        "/inputs/golden/TREE",
        "regular",
        golden_sha,
        golden_status,
        size=golden_size,
        uid=golden_uid,
        gid=golden_gid,
    )
    groups = {
        "authenticate-ubuntu-indexes": index_members,
        "authenticate-ubuntu-archives": archive_members,
        "authenticate-node-archive": [node_member],
        "hold-unrar-publisher-gap": [unrar_member],
