        algorithm_cause = "sha256_correspondence"
        algorithm_status = "NOT_PROVEN"
        if ubuntu_receipt["hash_header"] == "SHA512" and ubuntu_receipt["algorithm_status"] == "SUPPORTED":
            algorithm_cause = "sha512_correspondence"
