"""Full independently selected future actor/tool/runtime preimages.

These consumers compare held ordinary records and physical regular bytes.
They neither run a tool nor give an actor Root, publisher, or effect credit.
An external producer must supply the observations in a separately authorized
process. Digest labels without the corresponding bodies cannot close a join.
"""
from canonical import canonical_bytes, domain_digest
from contract import ContractError, is_digest
from resource_meter import checkpoint, reserve_allocation

ISSUERS = {
    'wheel': 'pypi-retained', 'native': 'system-native',
    'browser': 'browser-publisher', 'data': 'system-data',
    'candidate': 'owner-candidate', 'golden': 'owner-golden',
    'kernel': 'owner-kernel', 'unrar': 'rarlab-publisher',
    'member': 'independent-member', 'custody': 'independent-custody',
    'ubuntu-inrelease': 'ubuntu-archive', 'ubuntu-packages': 'ubuntu-archive',
    'ubuntu-archive': 'ubuntu-archive', 'node-archive': 'nodejs.org',
    'node-shasums256': 'nodejs.org', 'data-closure': 'system-data',
    'native-closure': 'system-native', 'snapshot': 'independent-snapshot',
    'operation': 'independent-operation',
}
METHODS = {
    'authenticate-ubuntu-indexes': 'index-selection',
    'authenticate-ubuntu-archives': 'archive-install',
    'authenticate-node-archive': 'node-install',
    'hold-unrar-publisher-gap': 'unrar-gap',
    'authenticate-wheels': 'wheel-install',
    'map-cpython-venv': 'venv-map', 'map-lib-dynload': 'dynload-map',
    'map-native-loader': 'loader-map', 'map-browser-resources': 'browser-install',
    'map-data-closure': 'data-map', 'bind-candidate': 'candidate-tree',
    'bind-golden': 'golden-tree', 'assemble-members': 'assemble',
    'write-final-manifest': 'manifest', 'external-custody': 'custody',
}

def exact(value, keys, cause):
    if type(value) is not dict or len(value) > 512:
        raise ContractError(cause)
    reserve_allocation((len(value)+len(keys))*80+128)
    if set(value) != set(keys):
        raise ContractError(cause)
    return value

def text(value, maximum=240, empty=False):
    if type(value) is not str or not (0 if empty else 1) <= len(value) <= maximum or '\x00' in value:
        raise ContractError('custody_linkage')
    return value

def integer(value, maximum=10**21):
    if type(value) is not int or not 0 <= value <= maximum:
        raise ContractError('custody_linkage')
    return value

def rows(value, maximum=512):
    if type(value) is not list or len(value) > maximum:
        raise ContractError('count')
    reserve_allocation(len(value) * 16 + 64)
    return value

def physical(ref, size, held):
    from performing_contracts import _member_bytes
    if type(ref) is not dict or set(ref) not in ({'kind','path','sha256'}, {'kind','path','sha256','document_sha256','offset','size'}):
        raise ContractError('operation_computation')
    text(ref['kind'], 40); text(ref['path']); integer(size, 80000000)
    if not is_digest(ref['sha256']):
        raise ContractError('operation_computation')
    return _member_bytes(held, ref, ref['sha256'], size)

def consume_runtime(body, members, held, section, target):
    runtime = exact(body['runtime'], (
        'producer_id', 'artifact_sha256', 'tool_sha256', 'environment_sha256',
        'observation_sha256', 'tool', 'environment', 'observation',
        'capability', 'verification_result'), 'custody_linkage')
    producer = text(body['producer_id'], 80)
    if runtime['producer_id'] != producer:
        raise ContractError('result_issuer')
    kind = ('operation' if section == 'operations' else 'snapshot' if section == 'snapshot'
            else target + '-closure' if section == 'closures'
            else 'custody' if target == 'a009-custody' else target.split('/', 1)[0])
    if kind not in ISSUERS:
        raise ContractError('document_kind')
    tool = exact(runtime['tool'], ('producer_id', 'executable', 'dependencies', 'argv', 'abi'), 'executable_binding')
    if tool['producer_id'] != producer or tool['abi'] != body['abi']:
        raise ContractError('executable_binding')
    executable = exact(tool['executable'], ('ref', 'size'), 'executable_binding')
    physical(executable['ref'], executable['size'], held)
    argv = rows(tool['argv'], 32)
    if not argv or argv[0] != executable['ref']['path']:
        raise ContractError('argv')
    for arg in argv: text(arg, 512)
    deps = rows(tool['dependencies'], 128)
    if not deps: raise ContractError('dependency_inventory_empty')
    seen = set()
    for dep in deps:
        exact(dep, ('ref', 'size', 'abi', 'custody'), 'dependency_inventory')
        path = dep['ref']['path']
        if path in seen or dep['abi'] != body['abi']['python_abi']:
            raise ContractError('dependency_inventory')
        seen.add(path); physical(dep['ref'], dep['size'], held)
        custody = exact(dep['custody'], ('producer_id', 'path', 'sha256', 'size', 'effects_granted'), 'custody_linkage')
        if custody != {'producer_id': producer, 'path': path, 'sha256': dep['ref']['sha256'], 'size': dep['size'], 'effects_granted': False}:
            raise ContractError('custody_linkage')
    environment = exact(runtime['environment'], ('producer_id', 'entries', 'kernel', 'process', 'observed_at_ns'), 'environment_entries')
    if environment['producer_id'] != producer: raise ContractError('result_issuer')
    names = set()
    for entry in rows(environment['entries'], 32):
        exact(entry, ('name', 'value'), 'environment_entries')
        text(entry['name'], 80); text(entry['value'], 512, empty=True)
        if entry['name'] in names: raise ContractError('environment_entries')
        names.add(entry['name'])
    kernel = exact(environment['kernel'], ('release', 'ref', 'size'), 'custody_linkage')
    text(kernel['release'], 128); physical(kernel['ref'], kernel['size'], held)
    process = exact(environment['process'], ('pid', 'started_ns', 'uid', 'gid'), 'custody_linkage')
    if integer(process['pid'], 4294967295) == 0: raise ContractError('custody_linkage')
    for key in ('started_ns', 'uid', 'gid'): integer(process[key])
    integer(environment['observed_at_ns'])
    observation = exact(runtime['observation'], (
        'producer_id', 'target', 'method', 'input_sha256', 'member_inventory_sha256',
        'dependencies_sha256', 'abi_sha256', 'resources_sha256', 'tool_sha256',
        'environment_sha256', 'exit_code', 'stdout', 'stderr', 'started_ns',
        'finished_ns', 'derivations', 'aggregate_resources'), 'custody_linkage')
    derived = {
        'input_sha256': domain_digest('friday.a117.performing-input.v1', body['input_body']),
        'member_inventory_sha256': domain_digest('friday.a117.installed-members.v1', body['members']),
        'dependencies_sha256': domain_digest('friday.a128.dependencies.v1', body['dependencies']),
        'abi_sha256': domain_digest('friday.a117.abi.v1', body['abi']),
        'resources_sha256': domain_digest('friday.a117.resources.v1', body['resources']),
        'tool_sha256': domain_digest('friday.a128.full-tool.v1', tool),
        'environment_sha256': domain_digest('friday.a128.full-environment.v1', environment),
    }
    if observation['producer_id'] != producer or observation['target'] != target or observation['exit_code'] != 0:
        raise ContractError('result_binding')
    method = METHODS.get(target) if section == 'operations' else kind
    if observation['method'] != method or any(observation[k] != v for k, v in derived.items()):
        raise ContractError('result_binding')
    for key in ('stdout', 'stderr'):
        stream = exact(observation[key], ('ref', 'size'), 'result_binding')
        physical(stream['ref'], stream['size'], held)
    started = integer(observation['started_ns']); finished = integer(observation['finished_ns'])
    if not process['started_ns'] <= started <= finished <= environment['observed_at_ns'] or finished - started > 4200 * 10**9:
        raise ContractError('whole_deadline')
    resources = exact(observation['aggregate_resources'], ('observer_id', 'scope', 'processes', 'peak_ram_bytes', 'read_bytes', 'output_bytes', 'implicit_io_status'), 'resource_contract')
    if resources['observer_id'] == producer or resources['scope'] != 'producer-and-all-helpers' or resources['implicit_io_status'] != 'OBSERVED':
        raise ContractError('resource_contract')
    text(resources['observer_id'], 80)
    if not rows(resources['processes'], 128) or process['pid'] not in resources['processes']:
        raise ContractError('resource_contract')
    if len(set(resources['processes'])) != len(resources['processes']): raise ContractError('resource_contract')
    for pid in resources['processes']:
        if integer(pid, 4294967295) == 0: raise ContractError('resource_contract')
    for key, maximum in (('peak_ram_bytes',8589934592),('read_bytes',40960000000),('output_bytes',33554432)):
        integer(resources[key], maximum)
    if resources['peak_ram_bytes'] == 0: raise ContractError('resource_contract')
    cap = exact(runtime['capability'], (
        'schema', 'issuer_id', 'actor_id', 'document_kind', 'method', 'target',
        'artifact_sha256', 'input_sha256', 'dependencies_sha256', 'abi_sha256',
        'resources_sha256', 'tool_sha256', 'environment_sha256', 'custody_sha256',
        'produced_by_this_package', 'effects_granted'), 'capability_binding')
    if cap['schema'] != 'friday.a128.class-capability.v1' or cap['issuer_id'] != ISSUERS[kind] or cap['actor_id'] != producer or cap['document_kind'] != kind or cap['target'] != target or cap['method'] != method:
        raise ContractError('document_kind')
    if cap['produced_by_this_package'] is not False or cap['effects_granted'] is not False:
        raise ContractError('self_issued_capability')
    if any(cap[k] != v for k, v in derived.items() if k != 'member_inventory_sha256'):
        raise ContractError('capability_binding')
    if not is_digest(runtime['artifact_sha256']) or cap['artifact_sha256'] != runtime['artifact_sha256'] or not is_digest(cap['custody_sha256']):
        raise ContractError('capability_binding')
    for key in ('tool_sha256', 'environment_sha256'):
        if runtime[key] != derived[key]: raise ContractError('result_binding')
    observation_sha = domain_digest('friday.a128.full-runtime-observation.v1', observation)
    if runtime['observation_sha256'] != observation_sha: raise ContractError('result_binding')
    result = exact(runtime['verification_result'], (
        'schema', 'issuer_id', 'actor_id', 'capability_sha256', 'observation_sha256',
        'artifact_sha256', 'member_inventory_sha256', 'custody_sha256',
        'decision', 'produced_by_this_package'), 'result_binding')
    capability_sha = domain_digest('friday.a128.class-capability.v1', cap)
    if result != {'schema':'friday.a128.class-result.v1', 'issuer_id':ISSUERS[kind], 'actor_id':producer, 'capability_sha256':capability_sha, 'observation_sha256':observation_sha, 'artifact_sha256':runtime['artifact_sha256'], 'member_inventory_sha256':derived['member_inventory_sha256'], 'custody_sha256':cap['custody_sha256'], 'decision':'STRUCTURALLY_BOUND', 'produced_by_this_package':False}:
        raise ContractError('result_binding')
    derivations = rows(observation['derivations'])
    paths = set()
    for row in derivations:
        checkpoint()
        exact(row, ('path', 'method', 'source_ref', 'source_size', 'selector'), 'operation_computation')
        path = row['path']
        if path in paths or path not in members or path not in body['output_paths']:
            raise ContractError('operation_computation')
        paths.add(path); member = members[path]
        if row['method'] != method: raise ContractError('operation_computation')
        # The actual input preimage and the exact selected output cannot be
        # replaced by a fixed filename projection or by a digest-only event.
        selector = exact(row['selector'], ('input_sha256','output_path','output_sha256','output_size'), 'operation_computation')
        if selector != {'input_sha256':derived['input_sha256'], 'output_path':path, 'output_sha256':member['content_sha256'], 'output_size':member['size']}:
            raise ContractError('operation_computation')
        if member['kind'] == 'regular':
            if row['source_ref'] != member['source_ref'] or row['source_size'] != member['size']:
                raise ContractError('operation_computation')
            physical(row['source_ref'], row['source_size'], held)
        elif row['source_ref'] is not None or row['source_size'] != 0:
            raise ContractError('operation_computation')
    if paths != set(body['output_paths']): raise ContractError('operation_computation')
    return {'status':'STRUCTURALLY_BOUND', 'document_kind':kind, 'issuer_id':ISSUERS[kind],
            'capability_sha256':capability_sha,
            'result_sha256':domain_digest('friday.a128.class-result.v1', result),
            'custody_sha256':cap['custody_sha256'], 'observation_sha256':observation_sha,
            'tool_sha256':derived['tool_sha256'], 'environment_sha256':derived['environment_sha256'],
            'full_body_consumed':True, 'current_observation':False,
            'publisher_proof':False, 'effects_granted':False}

sources.consumer/source/schema_validate.py:
"""Recursive exact-schema validator. Consumers compile a pinned schema before use."""

import json
import re

from contract import ContractError

PATTERN_NAMES = {
    "digest": re.compile(r"^[0-9a-f]{64}$"),
    "sha512": re.compile(r"^[0-9a-f]{128}$"),
    "fingerprint": re.compile(r"^[0-9A-F]{40}$"),
    "commit": re.compile(r"^[0-9a-f]{40}$"),
    "package_name": re.compile(r"^[a-z0-9][a-z0-9+.-]{0,63}$"),
    "version": re.compile(r"^[A-Za-z0-9.+:~-]{1,128}$"),
    "filename": re.compile(r"^[A-Za-z0-9._+/~-]{1,200}$"),
    "wheel_filename": re.compile(r"^[A-Za-z0-9._+-]{1,120}\.whl$"),
    "relative_path": re.compile(r"^[A-Za-z0-9._+/~-]{1,180}$"),
    "member_name": re.compile(r"^[a-z0-9][a-z0-9.+-]*/binary-amd64/Packages$"),
    "token": re.compile(r"^[A-Za-z0-9._:/-]{1,80}$"),
    "cause": re.compile(r"^[a-z0-9_]{1,64}$"),
    "tag": re.compile(r"^[A-Za-z0-9._+-]{1,80}$"),
    "requires_python": re.compile(r"^[A-Za-z0-9._<>=!,*]{1,80}$"),
    "requires_python_raw": re.compile(r"^[A-Za-z0-9._<>=!,*]{0,80}$"),
    "field_name": re.compile(r"^[A-Za-z0-9][A-Za-z0-9-]{0,63}$"),
    "abi": re.compile(r"^[A-Za-z0-9._+-]{1,40}$"),
}

SCHEMA_TYPES = {"object", "array", "string", "integer", "boolean", "const", "nullable", "enum"}
DIALECT = "friday.lab815.bounded-schema.v1"


def _schema_node(node, depth):
    if depth > 16 or type(node) is not dict:
        raise ContractError("schema_shape")
    kind = node.get("type")
    if kind not in SCHEMA_TYPES:
        raise ContractError("schema_type")
    if kind == "object":
        fields = node.get("fields")
        if node.get("exact") is not True or type(fields) is not dict or len(fields) > 64:
            raise ContractError("schema_object")
        for key, child in fields.items():
            if type(key) is not str:
                raise ContractError("schema_field")
            _schema_node(child, depth + 1)
        return
    if kind == "array":
        if type(node.get("min")) is not int or type(node.get("max")) is not int:
            raise ContractError("schema_array")
        if node["min"] < 0 or node["max"] < node["min"] or node["max"] > 512:
            raise ContractError("schema_array")
        _schema_node(node.get("items"), depth + 1)
        return
    if kind == "string":
        if type(node.get("min")) is not int or type(node.get("max")) is not int:
            raise ContractError("schema_string")
        pattern = node.get("pattern")
        if pattern is not None and pattern not in PATTERN_NAMES:
            raise ContractError("schema_pattern")
        return
    if kind == "integer":
        if type(node.get("minimum")) is not int or type(node.get("maximum")) is not int:
            raise ContractError("schema_integer")
        return
    if kind == "boolean":
        return
    if kind == "const":
        if "value" not in node:
            raise ContractError("schema_const")
        return
    if kind == "enum":
        values = node.get("values")
        if type(values) is not list or not values or len(values) > 32:
            raise ContractError("schema_enum")
        return
    _schema_node(node.get("of"), depth + 1)


def compile_schema(document):
    if type(document) is not dict:
        raise ContractError("schema_document")
    if document.get("dialect") != DIALECT:
        raise ContractError("schema_dialect")
    if type(document.get("name")) is not str or type(document.get("max_depth")) is not int:
        raise ContractError("schema_name")
    if not 1 <= document["max_depth"] <= 12:
        raise ContractError("schema_depth")
    _schema_node(document.get("root"), 1)
    return document


def validate_document(document, schema, depth=1):
    if type(schema) is not dict or schema.get("dialect") != DIALECT:
        raise ContractError("schema")
    if depth > schema["max_depth"]:
        raise ContractError("depth")
    _validate(document, schema["root"], depth, schema["max_depth"])


def validate_node(document, schema, path):
    if type(schema) is not dict or type(path) is not tuple:
        raise ContractError("schema")
    node = schema["root"]
    for part in path:
        if node.get("type") != "object" or part not in node["fields"]:
            raise ContractError("schema_path")
        node = node["fields"][part]
    _validate(document, node, 1, schema["max_depth"])


def _validate(document, node, depth, max_depth):
    if depth > max_depth:
        raise ContractError("depth")
    kind = node["type"]
    if kind == "nullable":
        if document is None:
            return
        _validate(document, node["of"], depth, max_depth)
        return
    if kind == "object":
        if type(document) is not dict:
            raise ContractError("object")
        fields = node["fields"]
        if set(document) != set(fields):
            raise ContractError("exact_keys")
        for key, child in fields.items():
            _validate(document[key], child, depth + 1, max_depth)
        return
    if kind == "array":
        if type(document) is not list:
            raise ContractError("array")
        if not node["min"] <= len(document) <= node["max"]:
            raise ContractError("count")
        seen = set()
        for item in document:
            _validate(item, node["items"], depth + 1, max_depth)
            if node.get("unique"):
                if type(item) is str:
                    marker = item
                else:
                    marker = json.dumps(item, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
                if marker in seen:
                    raise ContractError("duplicate_item")
                seen.add(marker)
        return
    if kind == "string":
        if type(document) is not str or not node["min"] <= len(document) <= node["max"]:
            raise ContractError("string")
        pattern = node.get("pattern")
        if pattern is not None and PATTERN_NAMES[pattern].fullmatch(document) is None:
            raise ContractError("pattern")
        return
    if kind == "integer":
        if type(document) is not int or isinstance(document, bool):
            raise ContractError("integer")
        if not node["minimum"] <= document <= node["maximum"]:
            raise ContractError("integer_bounds")
        return
    if kind == "boolean":
        if type(document) is not bool:
            raise ContractError("boolean")
        if "const" in node and document is not node["const"]:
            raise ContractError("const")
        return
    if kind == "const":
        if document != node["value"]:
            raise ContractError("const")
        return
    if kind == "enum":
        if document not in node["values"]:
            raise ContractError("enum")
        return
    raise ContractError("schema_type")

sources.consumer/source/semantics.py:
"""Cross-field correspondence that the exact schema shape cannot express alone."""

from contract import ContractError, is_digest, is_sha512


def validate_receipt_semantics(receipt):
    if receipt["publisher_proof"] is not False or receipt["effects_denied"] is not True:
        raise ContractError("receipt_credit")
    header = receipt["hash_header"]
    digest = receipt["hash_header_digest"]
    body = receipt["signed_body_sha256"]
    if body is not None and not is_digest(body):
        raise ContractError("signed_body_width")
    if header == "SHA512":
        if not is_sha512(digest):
            raise ContractError("hash_correspondence")
        if body is not None and len(body) != 64:
            raise ContractError("signed_body_width")
    elif header == "SHA256":
        if digest != body or not is_digest(digest):
            raise ContractError("hash_correspondence")
    elif header is None:
        if digest is not None:
            raise ContractError("hash_correspondence")
    else:
        raise ContractError("unsupported_hash")
    if receipt["proof_status"] in ("STRUCTURALLY_BOUND", "AUTHENTICATED"):
        for key in ("raw_document_sha256", "signed_body_sha256", "signature_armor_sha256"):
            if not is_digest(receipt[key]):
                raise ContractError("receipt_binding")
        if receipt["proof_status"] == "AUTHENTICATED" and (receipt["signature_verified"] is not True or not is_digest(receipt["verification_result_sha256"])):
            raise ContractError("verification_result_absent")
        if receipt["signature_verified"] is True and receipt["verification_result_sha256"] is None:
            raise ContractError("verification_result_absent")
    if receipt["proof_status"] == "NOT_PROVEN" and receipt["signature_verified"] is True:
        raise ContractError("verification_result_absent")
    return receipt


def validate_binding_semantics(record):
    evidence = record["compatibility_evidence"]
    statement = evidence["statement"]
    if statement == "MISMATCH":
        raise ContractError("compatibility_mismatch")
    if statement not in ("MATCH", "NOT_PROVEN"):
        raise ContractError("statement")
    if record["size"] is None or record["sha256"] is None:
        raise ContractError("material_incomplete")
    if statement == "MATCH":
        if evidence["issuer_id"] is None or evidence["evidence_sha256"] is None:
            raise ContractError("evidence_issuer")
        if evidence["target_sha256"] != record["sha256"]:
            raise ContractError("evidence_target")
    return record

sources.consumer/source/whole_join.py:
"""Whole publisher joins for the nine Sol037 residuals.

Source correspondence only. Absence of a future typed input stays
NOT_PROVEN. No cap, sentinel, or authority flag is relaxed here.
"""

from canonical import domain_digest
from contract import ContractError, is_digest
from resource_meter import HashlibProxy

hashlib = HashlibProxy()

BODY_FIELDS = (
    "members",
    "dependencies",
    "abi",
    "resources",
    "custody",
)


def exact_path_name(path, needle):
    if type(path) is not str or type(needle) is not str or needle == "":
        return False
    if path == needle:
        return True
    if needle.startswith("/") and path == needle[1:]:
        return True
    if "/" in needle:
        return False
    return path.rsplit("/", 1)[-1] == needle


def clear_body_aliases(presented):
    if type(presented) is not dict:
        return 0
    cleared = 0
    for key, value in list(presented.items()):
        if type(value) is bytes:
            presented[key] = None
            cleared += 1
    return cleared


class alias_window:
    def __init__(self, presented):
        self.presented = presented

    def __enter__(self):
        return self.presented

    def __exit__(self, exc_type, exc, tb):
        clear_body_aliases(self.presented)
        return False


def bind_other_document(row, contract, custody_body, selected_bound, performing=None):
    cap = contract.get("capability") if type(contract) is dict else None
    result = contract.get("verification_result") if type(contract) is dict else None
    actor = {
        "document_kind": row["document_kind"],
        "key_fingerprint": None if type(cap) is not dict else cap.get("key_fingerprint"),
        "path": row["path"],
        "produced_by_this_package": False,
        "result_sha256": None if type(result) is not dict else domain_digest(
            "friday.lab815.verification-result.v1", result
        ),
        "runtime": "NOT_RUN",
        "sha256": row["sha256"],
        "size": row["size"],
    }
    # Actor custody is a later domain. It is not written back into raw custody.
    actor_sha = domain_digest("friday.lab839.external-actor-custody.v1", actor)
    # An OpenPGP Ubuntu/Node capability cannot be promoted into an unrelated
    # class actor. That role stays separate from a typed installed observation.
    if cap is not None or result is not None:
        raise ContractError('document_kind')
    observation_closed = bool(performing is not None and
        performing['status']=='STRUCTURALLY_BOUND' and custody_body is not None and selected_bound)
    if observation_closed:
        actor=performing['body']['custody']
        actor_sha=performing['custody_sha256']
    runtime_join = None if performing is None else performing.get('runtime_consumer')
    runtime_closed = bool(observation_closed and type(runtime_join) is dict
        and runtime_join.get('status') == 'STRUCTURALLY_BOUND'
        and runtime_join.get('full_body_consumed') is True
        and runtime_join.get('document_kind') == row['document_kind']
        and runtime_join.get('custody_sha256') == domain_digest('friday.sol037.document-custody.v1', custody_body))
    return {
        "actor_custody": actor,
        "actor_custody_sha256": actor_sha,
        "cause": "full_future_class_actor_consumed" if runtime_closed else "full_material_selector_runtime_inventory_absent",
        'installed_observation_status':'STRUCTURALLY_BOUND' if observation_closed else 'NOT_PROVEN',
        "material_status": "STRUCTURALLY_BOUND" if runtime_closed else "NOT_PROVEN",
        "publisher_proof": False,
        "runtime": "NOT_RUN",
        'class_runtime_consumer':runtime_join,
    }


def join_node_projection(node, expected_node):
    if type(node) is not dict or type(expected_node) is not dict:
        return {
            "cause": "node_projection_absent",
            "publisher_proof": False,
            "runtime": "NOT_RUN",
            "status": "NOT_PROVEN",
        }
    archive_sha = node.get("archive_sha256")
    authoritative = expected_node.get("authoritative_sha256")
    diagnostic = expected_node.get("diagnostic_sha256")
    name_ok = node.get("archive_filename") == expected_node.get("filename")
    size_ok = node.get("archive_size") == expected_node.get("size")
    sha_ok = is_digest(authoritative) and archive_sha == authoritative
    diagnostic_rejected = not (archive_sha == diagnostic and archive_sha != authoritative)
    closed = bool(
        name_ok and size_ok and sha_ok and diagnostic_rejected and node.get("full_contract_closed") is True
    )
    return {
        "cause": "node_projected_metadata",
        "diagnostic_rejected": bool(diagnostic_rejected),
        "name_ok": bool(name_ok),
        "publisher_proof": False,
        "runtime": "NOT_RUN",
        "sha_ok": bool(sha_ok),
        "size_ok": bool(size_ok),
        "status": "STRUCTURALLY_BOUND" if closed else "NOT_PROVEN",
    }


def _member_names(section):
    if type(section) is not dict:
        return None
    members = section.get("members")
    if type(members) is not list:
        return None
    found = []
    for item in members:
        if type(item) is str and item != "":
            found.append(item)
        elif type(item) is dict and type(item.get("name")) is str and item["name"] != "":
            found.append(item["name"])
        else:
            return None
    for key in BODY_FIELDS[1:]:
        if type(section.get(key)) is not dict or not section[key]:
            return None
    return found


def closure_join_status(parsed_bodies, data_packages, interpreter_packages):
    if type(parsed_bodies) is not dict or "data" not in parsed_bodies or "native" not in parsed_bodies:
        return "NOT_PROVEN"
    data_names = _member_names(parsed_bodies["data"])
    native_names = _member_names(parsed_bodies["native"])
    if data_names is None or native_names is None:
        return "NOT_PROVEN"
    have = set(data_names) | set(native_names)
    required = []
    for item in list(data_packages) + list(interpreter_packages):
        if type(item) is str and item != "":
            required.append(item)
        elif type(item) is dict and type(item.get("name")) is str:
            required.append(item["name"])
        else:
            return "NOT_PROVEN"
    if not required or any(name not in have for name in required):
        return "NOT_PROVEN"
    # This old five-field shape has no independent expected installed/edge/
    # ABI/runtime consumer. Full typed bodies are consumed by performing_contracts.
    return "NOT_PROVEN"


def _rows(items, fields):
    rows = []
    for item in items:
        if type(item) is not dict:
            raise ContractError("operation_dependency")
        rows.append({field: item.get(field) for field in fields})
    return rows


def operation_specific_inputs(name, members, expected, composition, presented):
    statuses = {item["status"] for item in members}
    status = members[0]["status"] if len(statuses) == 1 else "NOT_PROVEN"
    record = {
        "join_status": status,
        "member_count": len(members),
        "operation": name,
        "publisher_proof": False,
        "runtime": "NOT_RUN",
    }
    if name == "authenticate-ubuntu-indexes":
        record["indexes"] = _rows(
            expected["ubuntu_minimum"]["indexes"],
            ("id", "suite", "component", "packages_sha256", "size"),
        )
    elif name == "authenticate-ubuntu-archives":
        record["archives"] = _rows(
            composition["packages"],
            ("name", "version", "architecture", "filename", "sha256", "size"),
        )
    elif name == "authenticate-node-archive":
        node = expected["node"]
        record["node"] = {
            "authoritative_sha256": node.get("authoritative_sha256"),
            "diagnostic_sha256": node.get("diagnostic_sha256"),
            "filename": node.get("filename"),
            "size": node.get("size"),
        }
    elif name == "hold-unrar-publisher-gap":
        record["unrar"] = {
            "publisher_digest": expected["unrar"].get("publisher_digest"),
            "status": status,
        }
    elif name == "authenticate-wheels":
        record["wheels"] = _rows(
            composition["wheels"],
            ("filename", "sha256", "size", "requires_python"),
        )
    elif name == "map-cpython-venv":
        record["venv_sha256"] = None if not members else members[0].get("content_sha256")
    elif name == "map-lib-dynload":
        record["lib_dynload"] = presented.get("lib_dynload")
    elif name == "map-native-loader":
        record["loader_sha256"] = presented.get("loader_sha256")
    elif name == "map-browser-resources":
        record["browser"] = _rows(expected["browser"]["archives"], ("filename", "sha256", "size"))
    elif name == "map-data-closure":
        record["roles"] = [item["path"] for item in members]
    elif name == "bind-candidate":
        record["candidate"] = {
            "commit": expected["candidate"]["commit"],
            "tree": expected["candidate"]["tree"],
        }
    elif name == "bind-golden":
        record["golden_sha256"] = presented.get("golden_sha256")
    elif name == "assemble-members":
        record["predecessor_sha256"] = None if not members else members[0].get("input_sha256")
    elif name == "write-final-manifest":
        record["emitted_member_sha256"] = None if not members else members[0].get("content_sha256")
    elif name == "external-custody":
        custody = presented.get("custody")
        record["custody_sha256"] = custody.get("sha256") if type(custody) is dict else None
    else:
        raise ContractError("recipe_operations")
    return record


def bind_member_hierarchy(members):
    by_path = {}
    unknown = 0
    inconsistent = 0
    for member in members:
        path = member["path"]
        roots=('/opt/friday/quality-toolchain/venv','/work/candidate','/inputs/golden')
        parent = "" if path in roots else path.rsplit("/", 1)[0] if "/" in path else ""
        if member.get("parent_path") != parent:
            inconsistent += 1
        if path in by_path:
            inconsistent += 1
        by_path[path] = member
        if member.get("device") is None or member.get("uid") is None or member.get("gid") is None:
            unknown += 1
    for member in members:
        parent = member.get("parent_path") or ""
        if parent == "":
            continue
        if parent not in by_path:
            inconsistent += 1
            continue
        holder = by_path[parent]
        if holder.get("kind") != "directory":
            inconsistent += 1
        if member.get("device") is not None and holder.get("device") not in (None, member.get("device")):
            inconsistent += 1
        for key in ("uid", "gid"):
            if member.get(key) is not None and holder.get(key) not in (None, member.get(key)):
                inconsistent += 1
    closed = unknown == 0 and inconsistent == 0 and len(members) > 0
    return {
        "closed": closed,
        "inconsistent": inconsistent,
        "member_count": len(members),
        "publisher_proof": False,
        "runtime": "NOT_RUN",
        "status": "STRUCTURALLY_BOUND" if closed else "NOT_PROVEN",
        "unknown_device_or_owner": unknown,
    }


def a009_domain_map(emitted_body, manifest, presented, operations, custody_consumer=None):
    emitted_sha = None
    if type(emitted_body) is str:
        emitted_sha = hashlib.sha256(emitted_body.encode("ascii")).hexdigest()
    inventory_sha = manifest.get("manifest_sha256") if type(manifest) is dict else None
    custody = presented.get("custody") if type(presented) is dict else None
    custody_sha = custody.get("sha256") if type(custody) is dict else None
    body = {
        "custody_sha256": custody_sha,
        "domains_distinct": bool(
            emitted_sha is not None and inventory_sha is not None and emitted_sha != inventory_sha
        ),
        "emitted_manifest_file_sha256": emitted_sha,
        "inventory_manifest_sha256": inventory_sha,
        "operation_count": len(operations),
        "self_digest_excluded": True,
    }
    preimage=dict(body)
    body["domain_sha256"] = domain_digest("friday.lab839.a009-emitted-domain.v1", preimage)
    body['domain_preimage']=preimage
    body['custody_consumer']=custody_consumer
    body["closed"] = bool(body["domains_distinct"] and custody_consumer is not None
        and custody_consumer['status']=='STRUCTURALLY_BOUND'
        and custody_consumer['raw_sha256']==custody_sha
        and custody_consumer['body']['input_body'].get('inventory_manifest_sha256')==inventory_sha
        and custody_consumer['body']['input_body'].get('emitted_manifest_file_sha256')==emitted_sha)
    body["publisher_proof"] = False
    body["runtime"] = "NOT_RUN"
    return body


def admit_approved_kernel(artifacts, computed, pins):
    contract = computed.get("kernel_contract_sha256") if type(computed) is dict else None
    kernel_pins = []
    if type(pins) is list:
        for pin in pins:
            if type(pin) is dict and pin.get("document_kind") == "kernel":
                kernel_pins.append(pin)
    rows = []
    admitted = False
    if len(kernel_pins) == 2 and is_digest(contract):
        for pin in kernel_pins:
            digest = pin.get("sha256")
            size = pin.get("size")
            if not is_digest(digest) or type(size) is not int or isinstance(size, bool):
                rows = []
                break
            rows.append({"sha256": digest, "size": size,'path':pin['relative_path']})
        if len(rows) == 2 and len({row['path'] for row in rows})==2:
            rows.sort(key=lambda item: (item["sha256"], item["size"]))
            admitted = domain_digest("friday.lab839.kernel-addition.v1", rows) == contract
    for artifact in artifacts if type(artifacts) is list else []:
        if artifact.get("class") != "kernel":
            continue
        if artifact.get("upstream_authority") in (None, ""):
            artifact["upstream_authority"] = "NOT_PROVEN"
        if not admitted:
            artifact["upstream_authority"] = "NOT_PROVEN"
        else:
            chosen=[row for row in rows if row['path']==artifact['filename']]
            if len(chosen)!=1 or artifact.get('sha256')!=chosen[0]['sha256'] or artifact.get('size')!=chosen[0]['size']:
                admitted=False
                artifact['upstream_authority']='NOT_PROVEN'
    return {
        "admitted": admitted,
        "publisher_proof": False,
        "required_count": 2,
        "runtime": "NOT_RUN",
        "supplied_count": len(kernel_pins),
    }


def derive_root_input(approval, raw_receipt, computed, envelope, kernel, approval_result=None):
    cap = raw_receipt.get("verifier_capability") if type(raw_receipt) is dict else None
    dependencies = cap.get("dependencies") if type(cap) is dict else None
    environment = cap.get("environment_entries") if type(cap) is dict else None
    ordered = [
        {"step": "issuer", "value": approval.get("issuer_id")},
        {"step": "key", "value": approval.get("key_fingerprint")},
        {
            "step": "raw_result",
            "value": None if type(raw_receipt) is not dict else raw_receipt.get("verification_result_sha256"),
        },
        {"step": "material_capability", "value": cap},
        {"step": "root_capability", "value": approval.get("capability_sha256")},
        {"step": "root_verification_result", "value": approval_result},
        {
            "step": "dependency",
            "value": None if type(dependencies) is not list else domain_digest(
                "friday.lab839.capability-dependencies.v1", dependencies
            ),
        },
        {
            "step": "environment",
            "value": None if type(environment) is not list else domain_digest(
                "friday.lab839.capability-environment.v1", environment
            ),
        },
        {
            "step": "verifier",
            "value": None if type(cap) is not dict else {
                k:cap.get(k) for k in ('executable','executable_sha256','argv','algorithm_class','keyring_sha256')},
        },
        {"step": "actor_custody", "value": approval.get("custody_sha256")},
        {"step": "artifact_order", "value": envelope["owner_approval"]["artifact_order_sha256"]},
        {"step": "signer_set", "value": envelope["owner_approval"]["signer_set_sha256"]},
    ]
    values_closed = all(item["value"] not in (None, "") for item in ordered)
    material_closed=(type(cap) is dict and type(dependencies) is list and
        bool(dependencies) and type(environment) is list and
        is_digest(cap.get('executable_sha256')) and is_digest(cap.get('dependency_closure_sha256')) and
        is_digest(cap.get('environment_digest')) and raw_receipt.get('proof_status') in ('AUTHENTICATED','STRUCTURALLY_BOUND'))
    root_closed=(type(approval_result) is dict and approval_result.get('decision')=='AUTHENTICATED' and
        approval_result.get('capability_sha256')==approval.get('capability_sha256') and
        approval_result.get('custody_sha256')==approval.get('custody_sha256'))
    return {
        "closed": bool(values_closed and material_closed and root_closed and kernel.get("admitted") is True),
        "kernel": kernel,
        "ordered": ordered,
        "publisher_proof": False,
        "release_trusted": False,
        "runtime": "NOT_RUN",
    }


def expected_public_output(spec, golden=None):
    if type(spec) is not dict or "cause" not in spec or "stage" not in spec or "status" not in spec:
        raise ContractError("control_unknown")
    if golden is not None:
        # The independently selected full golden, never a stage/status summary.
        return golden
    if spec.get("match") == "refuse" or spec.get("status") == "REFUSED":
        return {
            "accepted": False,
            "cause": spec["cause"],
            "effects_denied": True,
            "go": False,
            "publisher_proof": False,
            "ready_for_exec": False,
            "schema": "friday.sol037.public-refusal.v1",
            "stage": spec["stage"],
            "status": "REFUSED",
        }
    return None

